import type { ComponentProps } from "react";
import { Fragment, type ReactNode } from "react";

import { cn } from "../lib/cn";
import { Avatar } from "../avatar/avatar";
import { Badge, type BadgeProps } from "../badge/badge";
import { Progress } from "../progress/progress";

/**
 * Cell helpers for DataTable columns. Each one is a plain component, so they also work
 * outside a table. Pass `highlight` from the cell context to keep search matches marked.
 */

export type Highlighter = (text: string | number | null | undefined) => ReactNode;

/* ---------- Search folding: case, accents and a few special letters ---------- */

const MARKS = /\p{M}/gu;
const SPECIAL: Record<string, string> = {
  ß: "ss",
  ẞ: "ss",
  æ: "ae",
  Æ: "ae",
  œ: "oe",
  Œ: "oe",
  ø: "o",
  Ø: "o",
  đ: "d",
  Đ: "d",
  ł: "l",
  Ł: "l",
  ı: "i",
};

function foldChar(char: string): string {
  const special = SPECIAL[char];
  if (special) return special;
  // "é" → "e", "İ" → "i", combining marks on their own → "".
  return char.normalize("NFD").replace(MARKS, "").toLowerCase();
}

/**
 * Text as the search compares it: lower case, accents removed, ß → ss, … so "cafe" finds
 * "Café", "istanbul" finds "İstanbul" and "strasse" finds "Straße".
 */
export function foldText(text: string): string {
  let out = "";
  for (const char of text) out += foldChar(char);
  return out;
}

/** Folded text plus, for each folded character, the index of the source character it came from. */
function foldWithMap(text: string) {
  let folded = "";
  const source: number[] = [];
  let index = 0;
  for (const char of text) {
    const f = foldChar(char);
    source.push(...Array.from({ length: f.length }, () => index));
    folded += f;
    index += char.length;
  }
  return { folded, source };
}

const markClass = cn(
  // A highlighter stroke: tinted fill plus an accent underline, readable in light and dark.
  "rounded-[0.2rem] bg-sheen-accent/20 text-sheen-fg [box-decoration-break:clone] [box-shadow:inset_0_-2px_0_var(--sheen-accent)]",
  "forced-colors:bg-[Mark] forced-colors:text-[MarkText] forced-colors:[box-shadow:none]",
);

/** Wrap every match of `query` in a <mark>. Case- and accent-insensitive, like the table search. */
export function highlightText(text: string | number | null | undefined, query: string): ReactNode {
  if (text === null || text === undefined) return null;
  const value = String(text);
  const q = foldText(query.trim());
  if (!q) return value;
  const { folded, source } = foldWithMap(value);
  const parts: ReactNode[] = [];
  let cursor = 0; // index into `value`
  let from = folded.indexOf(q);
  while (from !== -1) {
    const start = source[from] ?? 0;
    let end = (source[from + q.length - 1] ?? start) + 1;
    // Take the whole source character (surrogate pairs) and any combining marks after it.
    while (end < value.length && (source[from + q.length] ?? value.length) > end) end++;
    if (start >= cursor) {
      if (start > cursor) parts.push(<Fragment key={`t${cursor}`}>{value.slice(cursor, start)}</Fragment>);
      parts.push(
        <mark key={`m${start}`} className={markClass}>
          {value.slice(start, end)}
        </mark>,
      );
      cursor = end;
    }
    from = folded.indexOf(q, from + q.length);
  }
  if (parts.length === 0) return value;
  if (cursor < value.length) parts.push(<Fragment key={`t${cursor}`}>{value.slice(cursor)}</Fragment>);
  return parts;
}

/**
 * Highlight as a component: wraps every match of `query` in a `<mark>`, ignoring case and
 * accents (the same matching as the table search). Props: `text` (string, number, null or
 * undefined) and `query`.
 *
 * Accessibility: Uses the native `<mark>` element, which screen readers can announce as highlighted; forced colors use the system `Mark` colours.
 *
 * @example
 * ```tsx
 * import { Highlight } from "@sheenui/theme";
 *
 * export const Match = () => <Highlight text="Café Lumière" query="cafe" />;
 * ```
 *
 * @see /components/data-table
 */
export function Highlight({
  text,
  query,
}: {
  /** The text to show. A number is shown as is; null or undefined renders nothing. */
  text: string | number | null | undefined;
  /** The search text to mark inside `text`, matched case-insensitively. An empty string marks nothing. */
  query: string;
}) {
  return <>{highlightText(text, query)}</>;
}

/* ---------- Person: avatar + name + email ---------- */

/** Props of {@link UserCell}. */
export type UserCellProps = {
  /** The person's full name; also the avatar's initials. */
  name: string;
  /** Shows the secondary line under the name. */
  email?: string;
  /** Avatar image URL; initials show without it. */
  src?: string;
  /** Shows the presence dot on the avatar. */
  status?: "online" | "away" | "offline";
  /** The `highlight` function from the cell context, so search matches stay marked. */
  highlight?: Highlighter;
  /** Adds extra classes to the cell. */
  className?: string;
};

/**
 * A table cell for a person: avatar, name and an optional email. Use it inside a DataTable
 * column's `cell`, or on its own.
 *
 * Accessibility: The name sits right next to the avatar, so the avatar is hidden from screen readers (no double reading). Long names and emails stay on one line and end in an ellipsis instead of widening the column or splitting mid-word; the full value is the hover title and the text stays in the DOM for assistive tech.
 *
 * @example
 * ```tsx
 * import { UserCell } from "@sheenui/theme";
 *
 * export const Person = () => <UserCell name="Ada Lovelace" email="ada@example.com" status="online" />;
 * ```
 *
 * @see /components/data-table
 */
export function UserCell({ name, email, src, status, highlight = (t) => t, className }: UserCellProps) {
  return (
    <span className={cn("flex min-w-0 items-center gap-3", className)}>
      {/* The name is right beside it: the avatar is decorative here. */}
      <span aria-hidden className="inline-flex shrink-0">
        <Avatar name={name} src={src} size="sm" status={status} />
      </span>
      <span className="flex min-w-0 flex-col leading-tight">
        <span data-slot="user-cell-name" title={name} className="truncate font-medium text-sheen-fg">
          {highlight(name)}
        </span>
        {email && (
          <span data-slot="user-cell-email" title={email} className="truncate text-xs text-sheen-fg-muted">
            {highlight(email)}
          </span>
        )}
      </span>
    </span>
  );
}

/* ---------- Status badge ---------- */

/** The colour roles a status can map to: the {@link Badge} tones. */
export type StatusTone = NonNullable<BadgeProps["tone"]>;

/** Props of {@link StatusCell}. */
export type StatusCellProps = {
  /** The status text from your data, e.g. "active". */
  value: string;
  /** Tone per value, e.g. { active: "success", churned: "danger" }. Unknown values are neutral. */
  tones?: Record<string, StatusTone>;
  /** Display text (defaults to the value). */
  label?: ReactNode;
  /** Adds extra classes to the badge. */
  className?: string;
};

/**
 * A status as a dotted {@link Badge}. Map your values to tones with `tones`; anything unmapped
 * is neutral. The words are always shown, so colour is never the only signal.
 *
 * Accessibility: A badge with text; the dot is decorative.
 *
 * @example
 * ```tsx
 * import { StatusCell } from "@sheenui/theme";
 *
 * export const Status = () => <StatusCell value="active" tones={{ active: "success", churned: "danger" }} />;
 * ```
 *
 * @see /components/data-table
 */
export function StatusCell({ value, tones, label, className }: StatusCellProps) {
  const tone = tones?.[value] ?? "neutral";
  return (
    <Badge tone={tone} dot className={className}>
      {label ?? value}
    </Badge>
  );
}

/* ---------- Progress / usage ---------- */

/** Props of {@link ProgressCell}. */
export type ProgressCellProps = {
  /** 0–100. Values outside the range are clamped. */
  value: number;
  /** Accessible name of the bar, e.g. "Usage". */
  label: string;
  /** Adds extra classes to the cell. */
  className?: string;
};

/**
 * A small progress bar with the percentage beside it, for usage or completion columns.
 *
 * Accessibility: A `progressbar` named by `label`; the visible percentage is hidden from screen readers because the bar already announces it.
 *
 * @example
 * ```tsx
 * import { ProgressCell } from "@sheenui/theme";
 *
 * export const Usage = () => <ProgressCell value={72} label="Storage used" />;
 * ```
 *
 * @see /components/data-table
 */
export function ProgressCell({ value, label, className }: ProgressCellProps) {
  const pct = Math.round(Math.min(100, Math.max(0, value)));
  return (
    <span data-slot="progress-cell" className={cn("flex min-w-32 items-center gap-3", className)}>
      <Progress
        value={pct}
        showValue={false}
        label={<span className="sr-only">{label}</span>}
        className="flex-1 gap-0"
      />
      <span aria-hidden className="w-9 text-end text-xs text-sheen-fg-muted tabular-nums">
        {pct}%
      </span>
    </span>
  );
}

/* ---------- Currency ---------- */

const currencyFormatters = new Map<string, Intl.NumberFormat>();

/** `value` as money in `currency` (default "USD") for `locale` (default: the browser's), with `maximumFractionDigits` decimals (default 0). Formatters are cached. */
export function formatCurrency(value: number, currency = "USD", locale?: string, maximumFractionDigits = 0) {
  const key = `${locale ?? ""}|${currency}|${maximumFractionDigits}`;
  let format = currencyFormatters.get(key);
  if (!format) {
    format = new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits });
    currencyFormatters.set(key, format);
  }
  return format.format(value);
}

/**
 * A money amount, right-aligned digits (tabular figures) formatted with Intl for the locale.
 * Props: `value` (number), `currency` (default "USD"), `locale` (default: the browser's),
 * `highlight` (the cell context's search highlighter).
 *
 * Accessibility: Plain text, so screen readers read the formatted amount. Pass `locale` for prerendered pages so the server and browser text match.
 *
 * @example
 * ```tsx
 * import { CurrencyCell } from "@sheenui/theme";
 *
 * export const Price = () => <CurrencyCell value={1299} currency="EUR" locale="de-DE" />;
 * ```
 *
 * @see /components/data-table
 */
export function CurrencyCell({
  value,
  currency = "USD",
  locale,
  highlight = (t) => t,
}: {
  /** The amount, in major units (12.5 is 12.50). */
  value: number;
  /** Sets the ISO 4217 currency code, for example "USD". */
  currency?: string;
  /** BCP 47 locale used to format the amount; defaults to the runtime's locale. */
  locale?: string;
  /** Highlights the part of the formatted amount that matches the table's search text. */
  highlight?: Highlighter;
}) {
  return (
    <span data-slot="currency-cell" className="tabular-nums">
      {highlight(formatCurrency(value, currency, locale))}
    </span>
  );
}

/* ---------- Relative date ---------- */

const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 24 * 3600],
  ["month", 30 * 24 * 3600],
  ["week", 7 * 24 * 3600],
  ["day", 24 * 3600],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
];

// One Intl formatter per locale (constructing them is the costly part of a date cell; a page of 100 rows made 300 of them).
const relativeFormatters = new Map<string, Intl.RelativeTimeFormat>();
const dateFormatters = new Map<string, Intl.DateTimeFormat>();

/** "3 days ago", "in 2 hours". `now` is injectable for deterministic output. */
export function formatRelativeDate(date: Date | string | number, now: Date | number = Date.now(), locale?: string) {
  const then = new Date(date).getTime();
  const seconds = Math.round((then - new Date(now).getTime()) / 1000);
  let format = relativeFormatters.get(locale ?? "");
  if (!format)
    relativeFormatters.set(locale ?? "", (format = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })));
  for (const [unit, size] of UNITS) {
    if (Math.abs(seconds) >= size || unit === "second") return format.format(Math.round(seconds / size), unit);
  }
  return format.format(0, "second");
}

/**
 * A date as relative text ("3 days ago", "in 2 hours") inside a `<time>`. The absolute date is
 * in the hover title and in the accessible name. Props: `value` (Date, ISO string or ms),
 * `now` (inject a fixed "now" for prerendered pages and tests; default: the current time),
 * `locale` (default: the browser's).
 *
 * Accessibility: Uses `<time dateTime>`; screen readers hear the relative text followed by the full date, while the visible text is the relative one only.
 *
 * @example
 * ```tsx
 * import { RelativeDateCell } from "@sheenui/theme";
 *
 * export const Updated = () => <RelativeDateCell value="2026-11-01T09:00:00Z" now={new Date("2026-11-08T09:00:00Z")} locale="en-US" />;
 * ```
 *
 * @see /components/data-table
 */
export function RelativeDateCell({
  value,
  now,
  locale,
}: {
  /** The moment to describe: a Date, an ISO string or a timestamp in ms. */
  value: Date | string | number;
  /** The reference time for "3 hours ago". Pass a fixed value on a prerendered page so the server and browser agree. */
  now?: Date | number;
  /** BCP 47 locale for the relative phrase; defaults to the runtime's locale. */
  locale?: string;
}) {
  const date = new Date(value);
  let dateFormat = dateFormatters.get(locale ?? "");
  if (!dateFormat)
    dateFormatters.set(locale ?? "", (dateFormat = new Intl.DateTimeFormat(locale, { dateStyle: "medium" })));
  const full = dateFormat.format(date);
  const relative = formatRelativeDate(date, now, locale);
  return (
    // The absolute date is in the title (hover) and in the accessible name.
    <time dateTime={date.toISOString()} title={full} className="whitespace-nowrap text-sheen-fg-muted">
      <span aria-hidden>{relative}</span>
      <span className="sr-only">
        {relative}, {full}
      </span>
    </time>
  );
}

/** Props of {@link CurrencyCell}. A money amount, right-aligned digits (tabular figures) formatted with Intl for the locale. */
export type CurrencyCellProps = ComponentProps<typeof CurrencyCell>;

/** Props of {@link RelativeDateCell}. A date as relative text ("3 days ago", "in 2 hours") inside a `<time>`. */
export type RelativeDateCellProps = ComponentProps<typeof RelativeDateCell>;

/** Props of {@link Highlight}. Text with the part that matches a query wrapped in `<mark>`. */
export type HighlightProps = ComponentProps<typeof Highlight>;

"use client";

import { Fragment, useRef, type RefObject } from "react";

import { Menu } from "@base-ui/react/menu";

import { Button } from "../button/button";
import { DotsIcon, SlidersIcon } from "./icons";
import {
  DataMenu,
  DataMenuCheckboxItem,
  DataMenuContent,
  DataMenuGroup,
  DataMenuItem,
  DataMenuLabel,
  DataMenuRadioGroup,
  DataMenuRadioItem,
  DataMenuSeparator,
  DataMenuTrigger,
} from "./menu";
import { iconButton } from "./shared";
import type { DataTableColumn, DataTableDensity, DataTableLabels, DataTableRowAction } from "./types";

/** The toolbar's View menu: row density and which columns are shown (never the last one). */
export function ViewMenu<TData>({
  labels,
  density,
  onDensityChange,
  columns,
  isVisible,
  visibleCount,
  onToggle,
}: {
  labels: DataTableLabels;
  density: DataTableDensity;
  onDensityChange: (d: DataTableDensity) => void;
  columns: DataTableColumn<TData>[];
  isVisible: (id: string) => boolean;
  visibleCount: number;
  onToggle: (id: string, on: boolean) => void;
}) {
  const hideable = columns.filter((c) => c.enableHiding !== false);
  return (
    <DataMenu>
      <DataMenuTrigger render={<Button variant="glass" className="h-11" leading={<SlidersIcon />} />}>
        <span className="max-sm:sr-only">{labels.view}</span>
      </DataMenuTrigger>
      <DataMenuContent align="end" className="w-56">
        <DataMenuGroup>
          <DataMenuLabel>{labels.density}</DataMenuLabel>
          <DataMenuRadioGroup value={density} onValueChange={(v) => onDensityChange(v as DataTableDensity)}>
            <DataMenuRadioItem value="comfortable" closeOnClick={false}>
              {labels.comfortable}
            </DataMenuRadioItem>
            <DataMenuRadioItem value="compact" closeOnClick={false}>
              {labels.compact}
            </DataMenuRadioItem>
          </DataMenuRadioGroup>
        </DataMenuGroup>
        {hideable.length > 0 && (
          <>
            <DataMenuSeparator />
            <DataMenuGroup>
              <DataMenuLabel>{labels.columns}</DataMenuLabel>
              {hideable.map((col) => {
                const on = isVisible(col.id);
                return (
                  <DataMenuCheckboxItem
                    key={col.id}
                    checked={on}
                    // Never hide the last visible column.
                    disabled={on && visibleCount <= 1}
                    onCheckedChange={(next) => onToggle(col.id, next)}
                  >
                    {col.header}
                  </DataMenuCheckboxItem>
                );
              })}
            </DataMenuGroup>
          </>
        )}
      </DataMenuContent>
    </DataMenu>
  );
}

/** What a row's trigger hands to the table's one shared row-actions menu when it opens. */
type RowMenuPayload<TData> = {
  row: TData;
  triggerRef: RefObject<HTMLButtonElement | null>;
  onFocusLost: () => void;
};

/** Links the row triggers to the one {@link RowActionsHost}. Create it once per table. */
export type RowMenuHandle<TData> = ReturnType<typeof createRowMenuHandle<TData>>;

/** Creates the handle that ties row triggers to the shared menu (safe on the server: it only builds an object). */
export function createRowMenuHandle<TData>() {
  return Menu.createHandle<RowMenuPayload<TData>>();
}

/**
 * The one menu behind every row's "..." button. A Base UI menu per row is costly to mount (a page of 100 rows
 * was 100 menus), so the rows render only a trigger and this host renders the open row's actions.
 */
export function RowActionsHost<TData>({
  handle,
  actionsFor,
}: {
  handle: RowMenuHandle<TData>;
  actionsFor: (row: TData) => DataTableRowAction<TData>[];
}) {
  return (
    <DataMenu handle={handle}>
      {({ payload }) =>
        payload ? (
          <DataMenuContent align="end">
            {actionsFor(payload.row).map((action, i) => (
              <Fragment key={`${action.label}-${i}`}>
                {action.separatorBefore && <DataMenuSeparator />}
                <DataMenuItem
                  tone={action.tone}
                  icon={action.icon}
                  disabled={action.disabled}
                  onClick={() => {
                    action.onSelect(payload.row);
                    // The row may be gone (deleted): don't drop focus on <body>.
                    window.requestAnimationFrame(() => {
                      if (!payload.triggerRef.current?.isConnected) payload.onFocusLost();
                    });
                  }}
                >
                  {action.label}
                </DataMenuItem>
              </Fragment>
            ))}
          </DataMenuContent>
        ) : null
      }
    </DataMenu>
  );
}

/** The "..." button at the end of a row; it opens the table's shared menu with this row's actions. */
export function RowActionsMenu<TData>({
  handle,
  label,
  hasActions,
  row,
  onFocusLost,
}: {
  handle: RowMenuHandle<TData>;
  label: string;
  /** False when this row has no actions: nothing is rendered. */
  hasActions: boolean;
  row: TData;
  /** Called when the row (and so this trigger) is gone after an action, e.g. Delete. */
  onFocusLost: () => void;
}) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  if (!hasActions) return null;
  return (
    <DataMenuTrigger
      ref={triggerRef}
      handle={handle}
      payload={{ row, triggerRef, onFocusLost }}
      data-dt-row-actions=""
      aria-label={label}
      className={iconButton}
    >
      <DotsIcon />
    </DataMenuTrigger>
  );
}

"use client";

import { useCallback, useDeferredValue, useId, useMemo, useRef, useState, type ReactNode } from "react";
import type { RowData } from "@tanstack/react-table";

import { cn } from "../lib/cn";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { useMediaQuery } from "../hooks/use-media-query";
import { highlightText } from "./cells";
import { HeaderRow } from "./header";
import { useTableModel } from "./model";
import {
  useAnnouncements,
  useCsvExport,
  useDebouncedSearch,
  useFocusRestore,
  useRowSelection,
  useScrollEdges,
  useScrollFocusClearance,
  useSelectionBarClearance,
  useTableState,
} from "./hooks";
import { useKeepFocusOnReorder } from "../motion/reorder";
import { defaultDataTableLabels } from "./labels";
import { RowActionsHost, createRowMenuHandle } from "./column-menu";
import { BodyRows, CardList, SkeletonRows } from "./rows";
import { SelectionBanner, SelectionBar } from "./selection";
import { EMPTY, EXPAND_W, PAGE_SIZES, SELECT_W, readValue, stringify, type GridEnv } from "./shared";
import { EdgeFades, EmptyBlock, ErrorBlock, LoadingOverlays, StaleErrorAlert } from "./states";
import { FilterChips, Toolbar } from "./toolbar";
import { TableFooter } from "./pagination";
import { VIRTUALIZE_FROM, useRowWindow } from "./row-window";
import type {
  DataTableColumn,
  DataTableFilterOption,
  DataTableLabels,
  DataTableProps,
  DataTableRowAction,
} from "./types";

/**
 * DataTable: a glass data grid built on TanStack Table v9 (headless) and SheenUI parts.
 *
 * Client-side by default (search, faceted filters, multi-sort, pagination happen in the
 * browser); pass `manual` + `rowCount` and the controlled state callbacks to let a server
 * do the work. Semantic <table> markup throughout: caption, scoped headers, aria-sort,
 * labelled checkboxes, and one polite live region that announces sort, page, selection
 * and result-count changes.
 *
 * Motion: rows slide to their new place when sorting, filtering or paging reorders them (`animateRows`,
 * on by default, built on `useRowReorder` from motion/reorder; see AnimatedList for the same effect on
 * any list), the selection bar slides up, detail rows open by height, the current-page pill
 * glides. Everything is instant (or a plain fade) with reduced motion. Glass elements are
 * animated themselves; no wrapper around glass is ever faded.
 */

/**
 * A full data table: global search with highlighted matches, multi-column sorting, faceted
 * filters, row selection with bulk actions, column visibility and density, paging, CSV export,
 * expandable rows, row action menus, a card layout on phones, and a server-side mode. Use it for
 * admin lists and reports; it works from plain row objects, with no table library to wire up.
 *
 * Props: see {@link DataTableProps}. Required: `data`, `columns` ({@link DataTableColumn}) and
 * `caption`. Features (all optional): `enableSearch` / `enableSelection` / `enableViewOptions` /
 * `enableExport` / `enableSorting` / `enableMultiSort`, `stickyFirstColumn`, `animateRows` (true), `maxHeight`,
 * `pageSizeOptions`, `defaultPageSize` (10), `hidePagination`, `rowActions`, `renderExpanded`,
 * `bulkActions`, `mobileLayout` ("scroll" | "cards"), `loading`, `error` / `onRetry`, `emptyState`,
 * `density`, controlled state for sorting, pagination, search, filters, selection and visibility,
 * `manual` server mode with `rowCount`, `labels`, `className`.
 *
 * Keyboard: Tab moves through the toolbar, sortable headers (Enter or Space sorts; Shift-click or Shift+Enter adds a sort), row checkboxes, row menus and the pager. Menus use arrow keys, Home / End, typeahead and Escape. A table that overflows becomes a keyboard-scrollable region.
 * Accessibility: A real `<table>` with a caption, `aria-sort` on sorted headers and a screen-reader sort hint; selection, filtering and paging changes are announced politely (result counts, "3 selected", the new page); checkboxes and menus carry row-specific names ("Select row Ravi Kumar"). The card layout keeps the same labels. Fully translatable through `labels`.
 * Glass: One glass panel around the table, plus the shared glass menus and selection bar; the table body itself is flat, so a page of tables stays within the backdrop-blur budget.
 * Motion: Rows slide to their new place on a sort or filter (`animateRows`, default true; transform only, `spring.smooth`; for other lists see `AnimatedList`), and the selection bar and menus use short transform and opacity transitions; reduced motion removes them.
 *
 * @example
 * ```tsx
 * import { DataTable, type DataTableColumn } from "@sheenui/theme";
 *
 * type Person = { id: string; name: string; role: string };
 *
 * const columns: DataTableColumn<Person>[] = [
 *   { id: "name", header: "Name", accessorKey: "name" },
 *   { id: "role", header: "Role", accessorKey: "role", filter: "faceted" },
 * ];
 *
 * export const People = ({ people }: { people: Person[] }) => (
 *   <DataTable data={people} columns={columns} caption="Team members" enableSelection />
 * );
 * ```
 *
 * @see /components/data-table
 */
export function DataTable<TData extends RowData>(props: DataTableProps<TData>) {
  const {
    data,
    columns,
    getRowId: getRowIdProp,
    getRowLabel,
    caption,
    showCaption = false,
    id,
    "aria-label": ariaLabel,
    className,
    tableClassName,
    enableSearch = true,
    searchDebounceMs = 200,
    enableSelection = false,
    enableViewOptions = true,
    enableExport = true,
    exportFilename = "data",
    onExport,
    enableSorting = true,
    enableMultiSort = true,
    stickyFirstColumn = true,
    animateRows = true,
    maxHeight,
    virtualize = "auto",
    pageSizeOptions = PAGE_SIZES,
    defaultPageSize = 10,
    hidePagination = false,
    rowActions,
    renderExpanded,
    bulkActions = EMPTY,
    toolbarLeft,
    toolbarRight,
    mobileLayout = "scroll",
    loading = false,
    error,
    onRetry,
    emptyState,
    manual = false,
    rowCount,
  } = props;

  const manualPagination = props.manualPagination ?? manual;
  const manualSorting = props.manualSorting ?? manual;
  const manualFiltering = props.manualFiltering ?? manual;
  const labels: DataTableLabels = useMemo(() => ({ ...defaultDataTableLabels, ...props.labels }), [props.labels]);
  const reduced = useSheenReducedMotion();
  const uid = useId();
  const captionId = `${uid}-caption`;
  const sortHintId = `${uid}-sort-hint`;
  const rowsPerPageId = `${uid}-rows-per-page`;

  /* ----- state (each slice controlled or uncontrolled) ----- */
  const {
    sorting: sortingNow,
    setSorting,
    pagination,
    setPagination,
    globalFilter,
    setGlobalFilter,
    columnFilters,
    setColumnFilters,
    rowSelection,
    setRowSelection,
    columnVisibility,
    setColumnVisibility,
    density,
    setDensity,
  } = useTableState(props, columns, defaultPageSize);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  // The header and the rows take a new sort together, in a low-priority render that React slices, so re-ordering
  // a long page never blocks input in one long task. Server-side sorting has nothing to re-order: no delay.
  const deferredSorting = useDeferredValue(sortingNow);
  const sorting = manualSorting ? sortingNow : deferredSorting;

  const rootRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const headRef = useRef<HTMLTableSectionElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const chipsRef = useRef<HTMLDivElement>(null);
  const barRef = useRef<HTMLDivElement>(null);

  useKeepFocusOnReorder(scrollRef);
  const { focusAnchor, focusIfLost, focusRowActions } = useFocusRestore(scrollRef, searchRef);

  const resetPage = useCallback(
    () => setPagination((p) => (p.pageIndex === 0 ? p : { ...p, pageIndex: 0 })),
    [setPagination],
  );

  const { searchInput, setSearchInput, applySearch, clearSearch, query } = useDebouncedSearch({
    globalFilter,
    setGlobalFilter,
    resetPage,
    searchDebounceMs,
    searchRef,
  });

  /* ----- columns → TanStack, rows and paging ----- */
  const {
    colById,
    getRowId,
    table,
    rows,
    matchingRows,
    total,
    pageCount,
    page,
    from,
    to,
    visibleColumns,
    firstColumn,
    filtersActive,
    rowLabel,
  } = useTableModel({
    data,
    columns,
    getRowId: getRowIdProp,
    getRowLabel,
    enableSorting,
    enableMultiSort,
    sorting,
    setSorting,
    pagination,
    setPagination,
    query,
    setGlobalFilter,
    columnFilters,
    setColumnFilters,
    columnVisibility,
    setColumnVisibility,
    manualPagination,
    manualSorting,
    manualFiltering,
    rowCount,
    loading,
  });

  /* ----- selection (row ids; persists across pages and sorting) ----- */
  const {
    selectedCount,
    selectedMatching,
    hiddenSelected,
    pageIds,
    allPageSelected,
    somePageSelected,
    setSelected,
    clearSelection,
    toggleRow,
    selectedRows,
  } = useRowSelection({
    data,
    getRowId,
    rows,
    matchingRows,
    table,
    rowSelection,
    setRowSelection,
    manualPagination,
    pagination,
  });

  /* ----- live region ----- */
  const { message, announce } = useAnnouncements({
    globalFilter,
    columnFilters,
    sorting,
    pagination,
    selectedCount,
    loading,
    total,
    page,
    pageCount,
    labels,
    colById,
    data,
    manualFiltering,
  });

  /* ----- filters ----- */
  const facetedColumns = columns.filter((c) => c.filter === "faceted");
  const filterValues = (columnId: string) => columnFilters.find((f) => f.id === columnId)?.value ?? EMPTY;
  const setFilter = (columnId: string, values: string[]) => {
    setColumnFilters((prev) => {
      const rest = prev.filter((f) => f.id !== columnId);
      return values.length ? [...rest, { id: columnId, value: values }] : rest;
    });
    resetPage();
  };
  const clearFilters = () => {
    setColumnFilters([]);
    resetPage();
    focusIfLost(
      () => searchRef.current ?? rootRef.current?.querySelector<HTMLElement>("[data-dt-filter]") ?? focusAnchor(),
    );
  };
  const facetOptions = (col: DataTableColumn<TData>): DataTableFilterOption[] => {
    const raw = manualFiltering ? null : table.getColumn(col.id)?.getFacetedUniqueValues();
    // TanStack keys counts by the raw value (number, boolean, …); options and filters use strings.
    let counts: Map<string, number> | null = null;
    if (raw) {
      counts = new Map();
      for (const [key, n] of raw as Map<unknown, number>) {
        const k = stringify(key);
        counts.set(k, (counts.get(k) ?? 0) + n);
      }
    }
    const base =
      col.filterOptions ??
      [...(counts?.keys() ?? [])]
        .filter((v) => v !== "")
        .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
        .map((v) => ({ value: v, label: v }));
    return base.map((o: DataTableFilterOption) => ({ ...o, count: counts ? (counts.get(o.value) ?? 0) : o.count }));
  };

  /* ----- export ----- */
  const { canExportAll, runExport } = useCsvExport({
    enableExport,
    manualPagination,
    onExport,
    exportFilename,
    selectedRows,
    matchingRows,
    visibleColumns,
    labels,
    announce,
  });

  /* ----- layout ----- */
  const narrow = useMediaQuery("(max-width: 639.98px)");
  const cards = narrow && mobileLayout === "cards";
  const edges = useScrollEdges(scrollRef, headRef, cards);
  const actionsFor = useCallback(
    (row: TData): DataTableRowAction<TData>[] =>
      rowActions ? (typeof rowActions === "function" ? rowActions(row) : rowActions) : EMPTY,
    [rowActions],
  );
  const hasActions = Boolean(rowActions);
  const [rowMenu] = useState(createRowMenuHandle<TData>);
  const pinStartCols = stickyFirstColumn; // checkbox + chevron columns
  const pinFirst = stickyFirstColumn && Boolean(firstColumn);
  const firstLeft = (enableSelection ? SELECT_W : 0) + (renderExpanded ? EXPAND_W : 0);
  /** The start-pinned column that carries the edge shadow. */
  const lastPinned = pinFirst
    ? "first"
    : !pinStartCols
      ? null
      : renderExpanded
        ? "expand"
        : enableSelection
          ? "select"
          : null;
  // Phones: the pinned columns take at most about 45% of the screen (cell padding included); the rest scrolls beside them.
  // Only the value is set here; the cap itself is a `max-sm:` rule, so the server HTML and the hydrated page lay out alike.
  const pinCap = pinFirst ? `max(5rem, calc(45vw - ${firstLeft + (density === "compact" ? 1.5 : 2)}rem))` : undefined;
  const colCount = visibleColumns.length + (enableSelection ? 1 : 0) + (renderExpanded ? 1 : 0) + (hasActions ? 1 : 0);
  const initialLoading = loading && rows.length === 0 && !error;
  const refetching = loading && rows.length > 0;
  /** A request failed but the previous rows are still shown: the alert floats over them (no layout shift). */
  const staleError = Boolean(error) && rows.length > 0;
  const compact = density === "compact";
  const cellPad = compact ? "px-3 py-1.5" : "px-4 py-3";
  // Opaque once rows slide underneath: translucent pinned cells let the scrolled text ghost through.
  const pinnedBg = "group-data-scrolled-x/dt:bg-sheen-surface";

  const highlight = useCallback((text: string | number | null | undefined) => highlightText(text, query), [query]);

  const renderCell = useCallback(
    (col: DataTableColumn<TData>, row: TData, rowId: string): ReactNode => {
      const value = readValue(col, row);
      if (col.cell) return col.cell({ row, rowId, value, highlight, query, density });
      const text = stringify(value);
      return col.searchable === false ? text : highlight(text);
    },
    [highlight, query, density],
  );

  const toggleExpanded = useCallback((rowId: string) => setExpanded((e) => ({ ...e, [rowId]: !e[rowId] })), []);

  useScrollFocusClearance(scrollRef, headRef, cards);
  useSelectionBarClearance(rootRef, barRef, enableSelection);

  const env: GridEnv<TData> = {
    labels,
    enableSelection,
    renderExpanded,
    hasActions,
    compact,
    cellPad,
    pinStartCols,
    pinFirst,
    firstLeft,
    lastPinned,
    pinCap,
    pinnedBg,
    colCount,
    visibleColumns,
    colById,
    pageIds,
    allPageSelected,
    somePageSelected,
    setSelected,
    rowMenu,
  };

  const errorText = error === true ? null : error;
  const retry =
    onRetry &&
    (() => {
      onRetry();
      // The error (and its Retry button) usually goes away.
      focusIfLost(focusAnchor);
    });
  const errorBlock = <ErrorBlock labels={labels} errorText={errorText} retry={retry} loading={loading} />;
  const emptyBlock = emptyState ?? (
    <EmptyBlock
      labels={labels}
      query={query}
      filtersActive={filtersActive}
      clearSearch={clearSearch}
      clearFilters={clearFilters}
    />
  );

  const bodyState: ReactNode =
    error && rows.length === 0 ? errorBlock : !loading && rows.length === 0 ? emptyBlock : null;
  const hasBodyState = bodyState !== null;

  /* ----- table markup ----- */

  const windowed =
    !cards &&
    !initialLoading &&
    (virtualize === true || (virtualize === "auto" && maxHeight !== undefined && rows.length >= VIRTUALIZE_FROM));
  const rowIds = useMemo(() => rows.map((r) => r.id), [rows]);
  // Row heights from the skeleton (h-10 / h-[3.25rem]), until a real row has been measured.
  const { window: rowWindow, report: reportRowSize } = useRowWindow(scrollRef, rowIds, windowed, compact ? 40 : 52);
  const rowProps = {
    rowWindow,
    reportRowSize,
    env,
    rows,
    rowSelection,
    expanded,
    toggleExpanded,
    toggleRow,
    rowLabel,
    renderCell,
    actionsFor,
    focusRowActions,
    uid,
    reduced,
    animateRows,
  };
  const tableView = (
    <table
      data-slot="data-table-table"
      aria-busy={loading || undefined}
      aria-rowcount={rowWindow ? rows.length + 1 : undefined}
      aria-describedby={undefined}
      className={cn("w-full border-separate border-spacing-0 text-sm", compact && "text-[0.8125rem]")}
    >
      <caption
        id={captionId}
        className={showCaption ? "px-4 pt-4 pb-2 text-start text-base font-semibold text-sheen-fg" : "sr-only"}
      >
        {caption}
      </caption>
      <thead
        ref={headRef}
        className={cn(
          "sticky top-0 z-[2]",
          // Only tinted once rows slide underneath.
          "[&_th]:transition-[background-color] group-data-scrolled-y/dt:[&_th]:bg-sheen-surface",
        )}
      >
        <HeaderRow
          env={env}
          table={table}
          sorting={sorting}
          setSorting={setSorting}
          enableMultiSort={enableMultiSort}
          sortHintId={sortHintId}
          indexed={rowWindow !== null}
        />
      </thead>
      <tbody>
        {initialLoading ? (
          <SkeletonRows env={env} pageSize={pagination.pageSize} />
        ) : bodyState ? (
          <tr>
            <td colSpan={colCount} className="p-0">
              <div style={{ width: edges.width || undefined }} className="sticky start-0">
                {bodyState}
              </div>
            </td>
          </tr>
        ) : (
          <BodyRows {...rowProps} edgesWidth={edges.width} />
        )}
      </tbody>
    </table>
  );

  return (
    <div ref={rootRef} id={id} data-slot="data-table" className={cn("flex w-full min-w-0 flex-col gap-3", className)}>
      <Toolbar
        labels={labels}
        toolbarLeft={toolbarLeft}
        toolbarRight={toolbarRight}
        enableSearch={enableSearch}
        enableSorting={enableSorting}
        enableViewOptions={enableViewOptions}
        canExportAll={canExportAll}
        cards={cards}
        total={total}
        density={density}
        setDensity={setDensity}
        sorting={sorting}
        setSorting={setSorting}
        columns={columns}
        visibleColumns={visibleColumns}
        columnVisibility={columnVisibility}
        setColumnVisibility={setColumnVisibility}
        searchRef={searchRef}
        searchInput={searchInput}
        setSearchInput={setSearchInput}
        applySearch={applySearch}
        clearSearch={clearSearch}
        facetedColumns={facetedColumns}
        facetOptions={facetOptions}
        filterValues={filterValues}
        setFilter={setFilter}
        runExport={runExport}
      />
      {filtersActive && (
        <FilterChips
          columnFilters={columnFilters}
          colById={colById}
          labels={labels}
          chipsRef={chipsRef}
          searchRef={searchRef}
          setFilter={setFilter}
          clearFilters={clearFilters}
          focusIfLost={focusIfLost}
          focusAnchor={focusAnchor}
        />
      )}

      <div className={cn("glass-2 relative min-w-0 overflow-hidden rounded-sheen-xl", tableClassName)}>
        {enableSelection && !manualPagination && allPageSelected && total > rows.length && (
          <SelectionBanner
            labels={labels}
            total={total}
            pageRowCount={rows.length}
            selectedMatching={selectedMatching}
            matchingRows={matchingRows}
            setSelected={setSelected}
            clearSelection={clearSelection}
            focusIfLost={focusIfLost}
            focusAnchor={focusAnchor}
          />
        )}
        <div className="group/dtw relative">
          <div
            ref={scrollRef}
            // A named, focusable region only while it scrolls (WCAG 2.1.1); otherwise the table speaks for itself.
            role={edges.overflow ? "region" : undefined}
            aria-label={edges.overflow ? (ariaLabel ?? labels.scrollRegion(caption)) : undefined}
            // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- a scrollable region must be keyboard focusable (WCAG 2.1.1); focusable only while it scrolls
            tabIndex={edges.overflow ? 0 : -1}
            style={{
              // Cards flow with the page on phones: no small scroll box inside the scrolling page.
              maxHeight: cards ? undefined : maxHeight,
              // Keep focused cells clear of the sticky header and the pinned columns (WCAG 2.4.11).
              scrollPaddingBlockStart: cards ? undefined : edges.headerHeight,
              scrollPaddingInlineStart: cards ? undefined : edges.pinStart,
              scrollPaddingInlineEnd: cards ? undefined : edges.pinEnd,
            }}
            className={cn(
              "group/dt relative overflow-auto overscroll-x-contain [scrollbar-width:thin] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
              "rounded-t-[inherit]",
            )}
          >
            {cards ? (
              <CardList
                {...rowProps}
                captionId={captionId}
                caption={caption}
                showCaption={showCaption}
                initialLoading={initialLoading}
                hasBodyState={hasBodyState}
                bodyState={bodyState}
                pageSize={pagination.pageSize}
              />
            ) : (
              tableView
            )}
          </div>

          {/* Edge fades: there is more to scroll on that side. */}
          {!cards && <EdgeFades hasActions={hasActions} lastPinned={lastPinned} />}
          <LoadingOverlays
            cards={cards}
            headerHeight={edges.headerHeight}
            loading={loading}
            veil={refetching || staleError}
          />
        </div>
        {staleError && <StaleErrorAlert labels={labels} errorText={errorText} retry={retry} loading={loading} />}
        {!hidePagination && (
          <TableFooter
            labels={labels}
            caption={caption}
            pagination={pagination}
            setPagination={setPagination}
            pageSizeOptions={pageSizeOptions}
            rowsPerPageId={rowsPerPageId}
            initialLoading={initialLoading}
            from={from}
            to={to}
            total={total}
            page={page}
            pageCount={pageCount}
            cards={cards}
          />
        )}
      </div>

      {hasActions && <RowActionsHost handle={rowMenu} actionsFor={actionsFor} />}
      {enableSelection && (
        <SelectionBar
          barRef={barRef}
          count={selectedCount}
          hidden={hiddenSelected}
          labels={labels}
          reduced={reduced}
          onClear={clearSelection}
          onClosedWithFocus={() => focusAnchor()?.focus()}
          onExport={enableExport ? () => runExport("selected") : undefined}
          actions={bulkActions}
          getRows={selectedRows}
        />
      )}

      <span id={sortHintId} className="sr-only">
        {labels.sortHint}
      </span>
      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {message}
      </div>
    </div>
  );
}

"use client";

import type { RowData } from "@tanstack/react-table";

import { Checkbox } from "../checkbox/checkbox";
import { cn } from "../lib/cn";
import { SortIcon } from "./icons";
import {
  EXPAND_W,
  PIN_CAP_TH,
  SELECT_W,
  alignClass,
  cssLength,
  pinShadow,
  pinShadowEnd,
  pinStyle,
  preventShiftSelect,
  type DtTable,
  type GridEnv,
} from "./shared";
import type { DataTableSorting } from "./types";

/** The header row: select-all checkbox, expand column, sortable column headers (with `aria-sort`) and the actions column. */
export function HeaderRow<TData extends RowData>({
  env,
  table,
  sorting,
  setSorting,
  enableMultiSort,
  sortHintId,
  indexed,
}: {
  env: GridEnv<TData>;
  table: DtTable<TData>;
  sorting: DataTableSorting;
  setSorting: (sorting: DataTableSorting) => void;
  enableMultiSort: boolean;
  sortHintId: string;
  /** Row windowing is on: the header is row 1 of the table. */
  indexed?: boolean;
}) {
  const {
    labels,
    enableSelection,
    renderExpanded,
    hasActions,
    compact,
    pinStartCols,
    pinFirst,
    firstLeft,
    lastPinned,
    pinCap,
    pinnedBg,
    visibleColumns,
    pageIds,
    allPageSelected,
    somePageSelected,
    setSelected,
  } = env;
  /** Header click: TanStack's cycle, except that a plain click inside a multi-sort makes that column the only sort. */
  const onSortClick = (colId: string, multi: boolean) => {
    const index = sorting.findIndex((s) => s.id === colId);
    const entry = sorting[index];
    if (!multi && sorting.length > 1 && entry) {
      // Never wipe every sort with one plain click: keep this column, flip its direction.
      setSorting([{ id: colId, desc: !entry.desc }]);
      return;
    }
    table.getColumn(colId)?.toggleSorting(undefined, multi);
  };

  return (
    <tr aria-rowindex={indexed ? 1 : undefined}>
      {enableSelection && (
        <th
          scope="col"
          data-pin={pinStartCols ? "start" : undefined}
          style={{ width: `${SELECT_W}rem`, minWidth: `${SELECT_W}rem`, ...(pinStartCols ? pinStyle(0) : {}) }}
          className={cn(
            "border-b border-sheen-border ps-4 pe-0 text-start",
            pinStartCols && ["sticky z-[3]", pinnedBg],
            lastPinned === "select" && pinShadow,
          )}
        >
          {/* The checkbox names the column; no extra "Select" text to read twice. */}
          <Checkbox
            data-dt-anchor=""
            aria-label={labels.selectAllOnPage}
            checked={allPageSelected}
            indeterminate={somePageSelected}
            disabled={pageIds.length === 0}
            onCheckedChange={() => setSelected(pageIds, !allPageSelected)}
          />
        </th>
      )}
      {renderExpanded && (
        <th
          scope="col"
          data-pin={pinStartCols ? "start" : undefined}
          style={{
            width: `${EXPAND_W}rem`,
            minWidth: `${EXPAND_W}rem`,
            ...(pinStartCols ? pinStyle(enableSelection ? `${SELECT_W}rem` : 0) : {}),
          }}
          className={cn(
            "border-b border-sheen-border px-0",
            pinStartCols && ["sticky z-[3]", pinnedBg],
            lastPinned === "expand" && pinShadow,
          )}
        >
          <span className="sr-only">{labels.expandColumn}</span>
        </th>
      )}
      {visibleColumns.map((col, i) => {
        const pinned = pinFirst && i === 0;
        const column = table.getColumn(col.id);
        const canSort = Boolean(column?.getCanSort());
        const sortIndex = sorting.findIndex((s) => s.id === col.id);
        const entry = sorting[sortIndex];
        const dir = entry ? (entry.desc ? "desc" : "asc") : false;
        const right = (col.align ?? (col.numeric ? "right" : "left")) === "right";
        const capped = pinned && pinCap !== undefined;
        return (
          <th
            key={col.id}
            scope="col"
            data-pin={pinned ? "start" : undefined}
            // aria-sort belongs on one header only: the primary sort.
            aria-sort={
              sortIndex === 0
                ? dir === "asc"
                  ? "ascending"
                  : "descending"
                : canSort && sortIndex < 0
                  ? "none"
                  : undefined
            }
            style={{
              width: cssLength(col.width),
              // A wrapping column would otherwise collapse to its longest word once the table overflows.
              minWidth: cssLength(col.minWidth ?? (col.wrap ? col.width : undefined)),
              ...(capped ? { "--dt-pin-cap": pinCap } : {}),
              ...(pinned ? pinStyle(`${firstLeft}rem`) : {}),
            }}
            className={cn(
              "border-b border-sheen-border text-xs font-semibold whitespace-nowrap text-sheen-fg-muted",
              compact ? "h-9 px-3" : "h-11 px-4",
              alignClass(col),
              canSort && (compact ? "px-1.5" : "px-2"),
              pinned && ["sticky z-[3]", pinnedBg, pinShadow],
              capped && PIN_CAP_TH,
              col.headerClassName,
            )}
          >
            {canSort ? (
              <button
                type="button"
                onClick={(event) => onSortClick(col.id, enableMultiSort && event.shiftKey)}
                onMouseDown={preventShiftSelect}
                aria-describedby={sortHintId}
                className={cn(
                  "group/sort relative inline-flex h-8 max-w-full items-center gap-1.5 rounded-sheen-sm px-2 font-semibold whitespace-nowrap",
                  "transition-colors hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus",
                  "any-pointer-coarse:after:absolute any-pointer-coarse:after:inset-x-0 any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:h-11 any-pointer-coarse:after:-translate-y-1/2",
                  dir && "text-sheen-fg",
                  right && "flex-row-reverse",
                )}
              >
                <span className="truncate">{col.header}</span>
                <span
                  aria-hidden
                  className={cn(
                    "flex items-center",
                    !dir && "opacity-45 group-hover/sort:opacity-80",
                    dir && "text-sheen-accent",
                  )}
                >
                  <SortIcon dir={dir} />
                  {sorting.length > 1 && sortIndex >= 0 && (
                    <span className="ms-0.5 text-2xs leading-none font-bold tabular-nums">{sortIndex + 1}</span>
                  )}
                </span>
                {/* State for secondary sorts (aria-sort only covers the primary one). */}
                {sortIndex > 0 && (
                  <span className="sr-only">
                    , {labels.sortPriority(sortIndex + 1)},{" "}
                    {dir === "desc" ? labels.sortDescending : labels.sortAscending}
                  </span>
                )}
              </button>
            ) : (
              col.header
            )}
          </th>
        );
      })}
      {hasActions && (
        <th
          scope="col"
          data-pin="end"
          style={{ width: "3.5rem", insetInlineEnd: 0 }}
          className={cn(
            "sticky z-[3] border-b border-sheen-border px-2",
            "group-data-more-end/dt:bg-sheen-surface",
            pinShadowEnd,
          )}
        >
          <span className="sr-only">{labels.actionsColumn}</span>
        </th>
      )}
    </tr>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from "react";
import type { RowData } from "@tanstack/react-table";

import { useControllable } from "../hooks/use-controllable";
import type { CsvValue } from "../lib/csv";
import { EMPTY, readValue, stringify, type DtRow, type DtTable } from "./shared";
import type {
  DataTableColumn,
  DataTableColumnFilters,
  DataTableDensity,
  DataTableLabels,
  DataTablePagination,
  DataTableProps,
  DataTableRowSelection,
  DataTableSorting,
} from "./types";
import { isRtlAt } from "../hooks/use-direction";

/* ---------- scroll edges ---------- */

/** What the scroll area reports about its edges: whether it overflows, its width, the header height and the widths of the pinned columns. */
export type Edges = {
  overflow: boolean;
  width: number;
  headerHeight: number;
  /** Width of the columns pinned at the start / end (scroll-padding keeps focus clear of them). */
  pinStart: number;
  pinEnd: number;
};

/**
 * Scroll position flags for edge shadows, plus the visible width (for sticky panels). The three
 * scroll flags (data-scrolled-x / data-more-end / data-scrolled-y) go straight onto the scroller
 * and its wrapper as attributes that CSS reads (group-data-*), never through React state: a
 * scroll that crosses an edge must not re-render the whole table (a 100+ ms commit with many rows).
 * Scroll events are coalesced to one measure per frame.
 */
export function useScrollEdges(
  ref: RefObject<HTMLElement | null>,
  headRef: RefObject<HTMLElement | null>,
  key: unknown,
) {
  const [edges, setEdges] = useState<Edges>({
    overflow: false,
    width: 0,
    headerHeight: 0,
    pinStart: 0,
    pinEnd: 0,
  });
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const update = () => {
      const maxX = el.scrollWidth - el.clientWidth;
      const x = Math.abs(el.scrollLeft); // negative in RTL
      let pinStart = 0;
      let pinEnd = 0;
      headRef.current?.querySelectorAll<HTMLElement>("th[data-pin]").forEach((th) => {
        if (th.dataset.pin === "end") pinEnd += th.offsetWidth;
        else pinStart += th.offsetWidth;
      });
      for (const [name, on] of [
        ["data-scrolled-x", x > 1],
        ["data-more-end", maxX - x > 1],
        ["data-scrolled-y", el.scrollTop > 1],
      ] as const) {
        if (el.hasAttribute(name) !== on) {
          el.toggleAttribute(name, on);
          el.parentElement?.toggleAttribute(name, on);
        }
      }
      const next: Edges = {
        overflow: maxX > 1 || el.scrollHeight - el.clientHeight > 1,
        width: el.clientWidth,
        headerHeight: headRef.current?.offsetHeight ?? 0,
        pinStart,
        pinEnd,
      };
      setEdges((prev) => ((Object.keys(next) as (keyof Edges)[]).every((k) => prev[k] === next[k]) ? prev : next));
    };
    update();
    let frame = 0;
    const onScroll = () => {
      if (!frame)
        frame = requestAnimationFrame(() => {
          frame = 0;
          update();
        });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      el.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, [ref, headRef, key]);
  return edges;
}

/* ---------- controlled / uncontrolled state ---------- */

/**
 * The seven state slices of the table, each controlled by its prop or kept inside (`useControllable`):
 * sorting, pagination, global filter, column filters, row selection, column visibility and density.
 */
export function useTableState<TData>(
  props: DataTableProps<TData>,
  columns: DataTableColumn<TData>[],
  defaultPageSize: number,
) {
  const [sorting, setSorting] = useControllable<DataTableSorting>(
    props.sorting,
    props.defaultSorting ?? EMPTY,
    props.onSortingChange,
  );
  const [pagination, setPagination] = useControllable<DataTablePagination>(
    props.pagination,
    { pageIndex: 0, pageSize: defaultPageSize },
    props.onPaginationChange,
  );
  const [globalFilter, setGlobalFilter] = useControllable<string>(
    props.globalFilter,
    props.defaultGlobalFilter ?? "",
    props.onGlobalFilterChange,
  );
  const [columnFilters, setColumnFilters] = useControllable<DataTableColumnFilters>(
    props.columnFilters,
    props.defaultColumnFilters ?? EMPTY,
    props.onColumnFiltersChange,
  );
  const [rowSelection, setRowSelection] = useControllable(
    props.rowSelection,
    props.defaultRowSelection ?? {},
    props.onRowSelectionChange,
  );
  const [columnVisibility, setColumnVisibility] = useControllable(
    props.columnVisibility,
    () => Object.fromEntries(columns.filter((c) => c.defaultHidden).map((c) => [c.id, false])),
    props.onColumnVisibilityChange,
  );
  const [density, setDensity] = useControllable<DataTableDensity>(
    props.density,
    props.defaultDensity ?? "comfortable",
    props.onDensityChange,
  );
  return {
    sorting,
    setSorting,
    pagination,
    setPagination,
    globalFilter,
    setGlobalFilter,
    columnFilters,
    setColumnFilters,
    rowSelection,
    setRowSelection,
    columnVisibility,
    setColumnVisibility,
    density,
    setDensity,
  };
}

/* ---------- focus ---------- */

/**
 * Never strand keyboard users on `<body>` when the focused control goes away: where focus lands (`focusAnchor`),
 * how to move it only if it was lost (`focusIfLost`) and how to refocus a row's menu after a row action (`focusRowActions`).
 */
export function useFocusRestore(
  scrollRef: RefObject<HTMLDivElement | null>,
  searchRef: RefObject<HTMLInputElement | null>,
) {
  /** Where focus lands when its control disappears: the header checkbox, else a header button, else the table region. */
  const focusAnchor = useCallback((): HTMLElement | null => {
    const region = scrollRef.current;
    if (!region) return searchRef.current;
    return (
      region.querySelector<HTMLElement>("[data-dt-anchor]:not([data-disabled])") ??
      region.querySelector<HTMLElement>("thead button") ??
      region
    );
  }, [scrollRef, searchRef]);
  /** After React has updated the DOM: if focus was lost (removed or disabled element), move it to `pick()`. */
  const focusIfLost = useCallback((pick: () => HTMLElement | null | undefined) => {
    window.requestAnimationFrame(() => {
      const active = document.activeElement as HTMLElement | null;
      const lost = !active || active === document.body || !active.isConnected || (active as HTMLButtonElement).disabled;
      if (lost) pick()?.focus();
    });
  }, []);
  /** A row went away from its own menu (Delete): focus the row that took its place, else the anchor. */
  const focusRowActions = useCallback(
    (index: number) => {
      const triggers = scrollRef.current?.querySelectorAll<HTMLElement>("[data-dt-row-actions]");
      const next = triggers && triggers.length > 0 ? triggers[Math.min(index, triggers.length - 1)] : undefined;
      (next ?? focusAnchor())?.focus();
    },
    [focusAnchor, scrollRef],
  );
  return { focusAnchor, focusIfLost, focusRowActions };
}

/* ---------- search ---------- */

/** The search box: typed text is debounced into the global filter; Enter applies at once and the filter can change from outside. */
export function useDebouncedSearch({
  globalFilter,
  setGlobalFilter,
  resetPage,
  searchDebounceMs,
  searchRef,
}: {
  globalFilter: string;
  setGlobalFilter: (value: string) => void;
  resetPage: () => void;
  searchDebounceMs: number;
  searchRef: RefObject<HTMLInputElement | null>;
}) {
  const [searchInput, setSearchInput] = useState(globalFilter);
  const applied = useRef(globalFilter);
  useEffect(() => {
    // The filter changed from outside (controlled reset, "Clear search"): mirror it in the box.
    if (globalFilter !== applied.current) {
      applied.current = globalFilter;
      setSearchInput(globalFilter);
    }
  }, [globalFilter]);
  const applySearch = useCallback(
    (value: string) => {
      applied.current = value;
      setGlobalFilter(value);
      resetPage();
    },
    [setGlobalFilter, resetPage],
  );
  useEffect(() => {
    if (searchInput === applied.current) return;
    const timer = window.setTimeout(() => applySearch(searchInput), searchDebounceMs);
    return () => window.clearTimeout(timer);
  }, [searchInput, searchDebounceMs, applySearch]);
  const query = globalFilter.trim();
  const clearSearch = () => {
    setSearchInput("");
    applySearch("");
    // The × (and the empty state's button) unmount once the box is empty.
    searchRef.current?.focus();
  };
  return { searchInput, setSearchInput, applySearch, clearSearch, query };
}

/* ---------- selection ---------- */

/** Row selection by id (it persists across pages and sorting): counts, page state, range toggling and the selected rows in table order. */
export function useRowSelection<TData extends RowData>({
  data,
  getRowId,
  rows,
  matchingRows,
  table,
  rowSelection,
  setRowSelection,
  manualPagination,
  pagination,
}: {
  data: TData[];
  getRowId: (row: TData, index: number) => string;
  rows: DtRow<TData>[];
  matchingRows: DtRow<TData>[];
  table: DtTable<TData>;
  rowSelection: DataTableRowSelection;
  setRowSelection: (update: DataTableRowSelection | ((prev: DataTableRowSelection) => DataTableRowSelection)) => void;
  manualPagination: boolean;
  pagination: DataTablePagination;
}) {
  const rowById = useMemo(() => new Map(data.map((row, i) => [getRowId(row, i), row])), [data, getRowId]);
  const seen = useRef(new Map<string, TData>());
  useEffect(() => {
    for (const [rowId, row] of rowById) seen.current.set(rowId, row);
  }, [rowById]);
  const selectedIds = useMemo(
    () =>
      Object.keys(rowSelection).filter(
        // Client-side: forget rows that no longer exist (deleted).
        (rowId) => rowSelection[rowId] && (manualPagination || rowById.has(rowId)),
      ),
    [rowSelection, rowById, manualPagination],
  );
  const selectedCount = selectedIds.length;
  // Client-side: how many of the selected rows pass the current search and filters.
  const selectedMatching = manualPagination
    ? selectedCount
    : matchingRows.reduce((n, r) => (rowSelection[r.id] ? n + 1 : n), 0);
  const hiddenSelected = selectedCount - selectedMatching;
  const pageIds = rows.map((r) => r.id);
  const pageSelected = pageIds.filter((rowId) => rowSelection[rowId]).length;
  const allPageSelected = pageIds.length > 0 && pageSelected === pageIds.length;
  const somePageSelected = pageSelected > 0 && !allPageSelected;
  const lastToggled = useRef<number | null>(null);

  const setSelected = useCallback(
    (ids: string[], on: boolean) =>
      setRowSelection((prev) => {
        if (on) return { ...prev, ...Object.fromEntries(ids.map((rowId) => [rowId, true])) };
        const drop = new Set(ids);
        return Object.fromEntries(Object.entries(prev).filter(([rowId]) => !drop.has(rowId)));
      }),
    [setRowSelection],
  );
  const clearSelection = useCallback(() => setRowSelection({}), [setRowSelection]);
  const toggleRow = (index: number, rowId: string, on: boolean, shift: boolean) => {
    // Shift-click: select (or clear) the whole range since the last toggled row on this page.
    if (shift && lastToggled.current !== null && lastToggled.current !== index) {
      const [a, b] = [Math.min(index, lastToggled.current), Math.max(index, lastToggled.current)];
      setSelected(pageIds.slice(a, b + 1), on);
    } else {
      setSelected([rowId], on);
    }
    lastToggled.current = index;
  };
  useEffect(() => {
    lastToggled.current = null;
  }, [pagination.pageIndex, pagination.pageSize]);

  /** Selected rows in table order: matching rows as sorted, then rows hidden by filters, then rows from other server pages. */
  const selectedRows = useCallback(() => {
    const pending = new Set(selectedIds);
    const out: TData[] = [];
    const take = (rowId: string, row: TData | undefined) => {
      if (row !== undefined && pending.delete(rowId)) out.push(row);
    };
    const ordered = manualPagination ? table.getRowModel().rows : table.getPrePaginatedRowModel().rows;
    for (const r of ordered) take(r.id, r.original);
    for (const [rowId, row] of rowById) take(rowId, row);
    for (const rowId of [...pending]) take(rowId, seen.current.get(rowId));
    return out;
  }, [selectedIds, rowById, manualPagination, table]);
  return {
    selectedCount,
    selectedMatching,
    hiddenSelected,
    pageIds,
    allPageSelected,
    somePageSelected,
    setSelected,
    clearSelection,
    toggleRow,
    selectedRows,
  };
}

/* ---------- live region ---------- */

/**
 * The polite live region: it announces sort, page, selection and result-count changes. Returns the text for the
 * region and `announce` for one-off messages (an export).
 */
export function useAnnouncements<TData>({
  globalFilter,
  columnFilters,
  sorting,
  pagination,
  selectedCount,
  loading,
  total,
  page,
  pageCount,
  labels,
  colById,
  data,
  manualFiltering,
}: {
  globalFilter: string;
  columnFilters: DataTableColumnFilters;
  sorting: DataTableSorting;
  pagination: DataTablePagination;
  selectedCount: number;
  loading: boolean;
  total: number;
  page: number;
  pageCount: number;
  labels: DataTableLabels;
  colById: Map<string, DataTableColumn<TData>>;
  data: TData[];
  manualFiltering: boolean;
}) {
  const [message, setMessage] = useState("");
  const flip = useRef(false);
  const announce = useCallback((text: string) => {
    flip.current = !flip.current;
    // A trailing no-break space toggles, so the same sentence is announced again.
    setMessage(text + (flip.current ? " " : ""));
  }, []);
  const filterKey = `${globalFilter}|${JSON.stringify(columnFilters)}`;
  const sortKey = JSON.stringify(sorting);
  const prev = useRef({
    filterKey,
    sortKey,
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    selectedCount,
    pending: false,
    pendingData: data,
  });
  useEffect(() => {
    const p = prev.current;
    const parts: string[] = [];
    let pending = p.pending;
    let pendingData = p.pendingData;
    if (filterKey !== p.filterKey) {
      pending = true;
      pendingData = data;
    }
    // Server-side, the count is only known once new rows arrive.
    const settled = !loading && (!manualFiltering || data !== pendingData);
    if (sortKey !== p.sortKey) {
      parts.push(
        sorting.length === 0
          ? labels.sortCleared
          : labels.sortedBy(
              sorting
                .map(
                  (s) =>
                    `${colById.get(s.id)?.header ?? s.id} ${s.desc ? labels.sortDescending : labels.sortAscending}`,
                )
                .join(`, ${labels.sortThen} `),
            ),
      );
    }
    if (pending && settled) {
      parts.push(labels.results(total));
      pending = false;
    } else if (pagination.pageSize !== p.pageSize && !pending) {
      parts.push(labels.pageSizeChanged(pagination.pageSize, page, pageCount));
    } else if (pagination.pageIndex !== p.pageIndex && !pending) {
      parts.push(labels.pageOf(page, pageCount));
    }
    if (selectedCount !== p.selectedCount) parts.push(labels.selectedCount(selectedCount));
    prev.current = {
      filterKey,
      sortKey,
      pageIndex: pagination.pageIndex,
      pageSize: pagination.pageSize,
      selectedCount,
      pending,
      pendingData,
    };
    if (parts.length) announce(parts.join(". "));
  }, [
    filterKey,
    sortKey,
    pagination.pageIndex,
    pagination.pageSize,
    selectedCount,
    loading,
    total,
    page,
    pageCount,
    sorting,
    labels,
    colById,
    announce,
    data,
    manualFiltering,
  ]);
  return { message, announce };
}

/* ---------- focus clearance (WCAG 2.4.11) ---------- */

/** Keeps focus inside the scroll area clear of the sticky header and the pinned columns (`scroll-padding` covers most cases; Chrome ignores it when the element is already partly visible). */
export function useScrollFocusClearance(
  scrollRef: RefObject<HTMLDivElement | null>,
  headRef: RefObject<HTMLTableSectionElement | null>,
  cards: boolean,
) {
  useEffect(() => {
    const region = scrollRef.current;
    if (!region || cards) return;
    const onFocusIn = (event: FocusEvent) => {
      const target = event.target as HTMLElement | null;
      if (!target || target === region || !target.closest("td, th")) return;
      window.requestAnimationFrame(() => {
        // Keyboard focus only: scrolling between mousedown and mouseup would swallow a click.
        if (document.activeElement !== target || !target.matches(":focus-visible")) return;
        // Sticky ancestors (the header row, pinned cells, detail panels) already stay in view on their axis.
        let stickyX = false;
        for (let el: HTMLElement | null = target; el && el !== region; el = el.parentElement) {
          if (el.tagName !== "THEAD" && getComputedStyle(el).position === "sticky") stickyX = true;
        }
        const inHead = Boolean(target.closest("thead"));
        const gap = 4;
        const box = region.getBoundingClientRect();
        const t = target.getBoundingClientRect();
        if (!inHead) {
          const top = box.top + region.clientTop + (headRef.current?.offsetHeight ?? 0) + gap;
          if (t.top < top) region.scrollTop -= top - t.top;
        }
        if (!stickyX) {
          const rtl = isRtlAt(region);
          const pins = region.querySelectorAll<HTMLElement>("thead th[data-pin]");
          let start = 0;
          let end = 0;
          pins.forEach((th) => (th.dataset.pin === "end" ? (end += th.offsetWidth) : (start += th.offsetWidth)));
          const left = box.left + region.clientLeft + (rtl ? end : start) + gap;
          const right = box.left + region.clientLeft + region.clientWidth - (rtl ? start : end) - gap;
          // scrollLeft grows towards the right in both directions (negative values in RTL).
          if (t.left < left) region.scrollLeft -= left - t.left;
          else if (t.right > right) region.scrollLeft += Math.min(t.right - right, t.left - left);
        }
      });
    };
    region.addEventListener("focusin", onFocusIn);
    return () => region.removeEventListener("focusin", onFocusIn);
  }, [cards, scrollRef, headRef]);
}

/** Scrolls the focused control clear of the floating selection bar. */
export function useSelectionBarClearance(
  rootRef: RefObject<HTMLDivElement | null>,
  barRef: RefObject<HTMLDivElement | null>,
  enableSelection: boolean,
) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root || !enableSelection) return;
    const onFocusIn = (event: FocusEvent) => {
      const target = event.target as HTMLElement | null;
      const bar = barRef.current;
      if (!target || !bar || bar.contains(target)) return;
      window.requestAnimationFrame(() => {
        if (!bar.isConnected || document.activeElement !== target || !target.matches(":focus-visible")) return;
        const b = bar.getBoundingClientRect();
        const t = target.getBoundingClientRect();
        if (!(t.bottom > b.top - 4 && t.top < b.bottom && t.right > b.left && t.left < b.right)) return;
        const previous = target.style.scrollMarginBottom;
        target.style.scrollMarginBottom = `${Math.ceil(b.height) + 32}px`;
        target.scrollIntoView({ block: "nearest", inline: "nearest" });
        target.style.scrollMarginBottom = previous;
      });
    };
    root.addEventListener("focusin", onFocusIn);
    return () => root.removeEventListener("focusin", onFocusIn);
  }, [enableSelection, rootRef, barRef]);
}

/* ---------- export ---------- */

/** CSV export of the filtered rows or the selected rows (or the `onExport` callback), announced in the live region. */
export function useCsvExport<TData extends RowData>({
  enableExport,
  manualPagination,
  onExport,
  exportFilename,
  selectedRows,
  matchingRows,
  visibleColumns,
  labels,
  announce,
}: {
  enableExport: boolean;
  manualPagination: boolean;
  onExport: DataTableProps<TData>["onExport"];
  exportFilename: string;
  selectedRows: () => TData[];
  matchingRows: DtRow<TData>[];
  visibleColumns: DataTableColumn<TData>[];
  labels: DataTableLabels;
  announce: (text: string) => void;
}) {
  // Server-side the table only has the current page: the toolbar export needs onExport there.
  const canExportAll = enableExport && (!manualPagination || Boolean(onExport));
  const runExport = (scope: "filtered" | "selected") => {
    const source = scope === "selected" ? selectedRows() : matchingRows.map((r) => r.original);
    if (onExport) {
      onExport(source, scope);
    } else {
      const cols = visibleColumns.filter((c) => c.enableExport !== false);
      const headers = cols.map((c) => c.header);
      const rows = source.map((row) =>
        cols.map((c): CsvValue => {
          if (c.exportValue) return c.exportValue(row);
          const value = readValue(c, row);
          return value instanceof Date || typeof value === "number" || typeof value === "boolean"
            ? value
            : stringify(value);
        }),
      );
      // The CSV writer loads on first export: no page that only shows the table pays for it.
      void import("../lib/csv").then(({ downloadCsv, toCsv }) => {
        downloadCsv(scope === "selected" ? `${exportFilename}-selected` : exportFilename, toCsv(headers, rows));
      });
    }
    announce(`${labels.exportCsv}: ${labels.results(source.length)}`);
  };
  return { canExportAll, runExport };
}

