"use client";

import { useCallback, useEffect, useMemo } from "react";
import { useTable, type RowData } from "@tanstack/react-table";

import { foldText } from "./cells";
import {
  features,
  inSetFilter,
  readValue,
  stringify,
  type RowLike,
  type SearchState,
  type Setter,
  type Updater,
} from "./shared";
import type {
  DataTableColumn,
  DataTableColumnFilters,
  DataTableColumnVisibility,
  DataTablePagination,
  DataTableProps,
  DataTableSorting,
} from "./types";

/**
 * Builds the TanStack table from the column definitions and the table state, and derives what the view needs:
 * the rows of the page, every matching row, the counts, the visible columns and each row's accessible label.
 * It also steps back to the last page when paging past the end (rows deleted, filters narrowed on the server).
 */
export function useTableModel<TData extends RowData>({
  data,
  columns,
  getRowId: getRowIdProp,
  getRowLabel,
  enableSorting,
  enableMultiSort,
  sorting,
  setSorting,
  pagination,
  setPagination,
  query,
  setGlobalFilter,
  columnFilters,
  setColumnFilters,
  columnVisibility,
  setColumnVisibility,
  manualPagination,
  manualSorting,
  manualFiltering,
  rowCount,
  loading,
}: {
  data: TData[];
  columns: DataTableColumn<TData>[];
  getRowId: DataTableProps<TData>["getRowId"];
  getRowLabel: DataTableProps<TData>["getRowLabel"];
  enableSorting: boolean;
  enableMultiSort: boolean;
  sorting: DataTableSorting;
  setSorting: Setter<DataTableSorting>;
  pagination: DataTablePagination;
  setPagination: Setter<DataTablePagination>;
  /** The applied (trimmed) search text. */
  query: string;
  setGlobalFilter: (value: string) => void;
  columnFilters: DataTableColumnFilters;
  setColumnFilters: Setter<DataTableColumnFilters>;
  columnVisibility: DataTableColumnVisibility;
  setColumnVisibility: Setter<DataTableColumnVisibility>;
  manualPagination: boolean;
  manualSorting: boolean;
  manualFiltering: boolean;
  rowCount: number | undefined;
  loading: boolean;
}) {
  const colById = useMemo(() => new Map(columns.map((c) => [c.id, c])), [columns]);
  const tableColumns = useMemo(
    () =>
      columns.map((col) => ({
        id: col.id,
        // null and undefined both sort last (sortUndefined only knows undefined).
        accessorFn: (row: TData) => {
          const value = readValue(col, row);
          return value === null ? undefined : value;
        },
        header: col.header,
        enableSorting: enableSorting && col.enableSorting !== false,
        enableMultiSort,
        enableHiding: col.enableHiding !== false,
        enableGlobalFilter: col.searchable !== false,
        enableColumnFilter: col.filter === "faceted",
        filterFn: inSetFilter,
        sortFn:
          typeof col.sortFn === "function"
            ? (
                (compare) => (a: RowLike<TData>, b: RowLike<TData>) =>
                  compare(a.original, b.original)
              )(col.sortFn)
            : (col.sortFn ?? (col.numeric ? "basic" : "alphanumeric")),
        sortUndefined: "last" as const,
        sortDescFirst: false,
      })),
    [columns, enableSorting, enableMultiSort],
  );

  // Only visible columns are searched: a match in a hidden column would show a row with nothing marked.
  const searchedColumns = columns
    .filter((c) => c.searchable !== false && columnVisibility[c.id] !== false)
    .map((c) => c.id)
    .join(",");
  const searchState = useMemo<SearchState | undefined>(
    () => (query ? { folded: foldText(query), columns: searchedColumns } : undefined),
    [query, searchedColumns],
  );
  const globalFilterFn = useMemo(() => {
    const searchers = new Map(columns.map((c) => [c.id, c.searchValue]));
    return (row: RowLike<TData>, columnId: string, filterValue: unknown) => {
      const q = (filterValue as SearchState | undefined)?.folded;
      if (!q) return true;
      const custom = searchers.get(columnId);
      const text = custom ? custom(row.original) : stringify(row.getValue(columnId));
      return foldText(text).includes(q);
    };
  }, [columns]);

  const getRowId = useCallback(
    (row: TData, index: number) => {
      if (getRowIdProp) return getRowIdProp(row, index);
      const maybe = (row as { id?: unknown }).id;
      return typeof maybe === "string" || typeof maybe === "number" ? String(maybe) : String(index);
    },
    [getRowIdProp],
  );

  const table = useTable<typeof features, TData>({
    features,
    columns: tableColumns,
    data,
    getRowId,
    // The search goes in as SearchState (re-filters when the visible columns change); callers only see the string.
    state: { sorting, pagination, globalFilter: searchState, columnFilters, columnVisibility },
    onSortingChange: (u) => setSorting(u),
    onPaginationChange: (u) => setPagination(u),
    onGlobalFilterChange: (u) => {
      const next: unknown = typeof u === "function" ? (u as (prev: unknown) => unknown)(searchState) : u;
      setGlobalFilter(typeof next === "string" ? next : "");
    },
    onColumnFiltersChange: (u) => setColumnFilters(u as Updater<DataTableColumnFilters>),
    onColumnVisibilityChange: (u) => setColumnVisibility(u),
    manualPagination,
    manualSorting,
    manualFiltering,
    rowCount: manualPagination ? (rowCount ?? data.length) : undefined,
    autoResetPageIndex: false,
    enableSorting,
    enableMultiSort,
    maxMultiSortColCount: 3,
    enableSortingRemoval: true,
    sortDescFirst: false,
    globalFilterFn,
    getColumnCanGlobalFilter: (column) =>
      (column.columnDef as { enableGlobalFilter?: boolean }).enableGlobalFilter !== false &&
      columnVisibility[column.id] !== false,
  });

  /* ----- derived ----- */
  const rows = table.getRowModel().rows;
  /** Every row that passes the search and filters, in table order (client-side); the page in server mode. */
  const matchingRows = manualPagination ? rows : table.getPrePaginatedRowModel().rows;
  const total = manualPagination ? (rowCount ?? data.length) : matchingRows.length;
  const pageCount = Math.max(1, Math.ceil(total / pagination.pageSize));
  const page = Math.min(pagination.pageIndex + 1, pageCount);
  const from = total === 0 ? 0 : pagination.pageIndex * pagination.pageSize + 1;
  const to = Math.min(total, pagination.pageIndex * pagination.pageSize + rows.length);
  const visibleColumns = table
    .getVisibleLeafColumns()
    .map((c) => colById.get(c.id))
    .filter((c): c is DataTableColumn<TData> => Boolean(c));
  const firstColumn = visibleColumns[0];
  const filtersActive = columnFilters.length > 0;

  // Paging past the end (rows deleted, filters narrowed on the server): step back to the last page.
  useEffect(() => {
    if (!loading && pagination.pageIndex > pageCount - 1) setPagination((p) => ({ ...p, pageIndex: pageCount - 1 }));
  }, [loading, pageCount, pagination.pageIndex, setPagination]);

  const rowLabel = useCallback(
    (row: TData, index: number) => {
      if (getRowLabel) return getRowLabel(row);
      const first = columns[0];
      if (!first) return String(index + 1);
      const value = readValue(first, row);
      return stringify(value) || String(index + 1);
    },
    [getRowLabel, columns],
  );
  return {
    colById,
    getRowId,
    table,
    rows,
    matchingRows,
    total,
    pageCount,
    page,
    from,
    to,
    visibleColumns,
    firstColumn,
    filtersActive,
    rowLabel,
  };
}

"use client";

import { memo, useId, useState } from "react";

import { Input } from "../input/input";
import { Pagination } from "../pagination/pagination";
import { Select } from "../select/select";
import type { DataTableLabels, DataTablePagination } from "./types";

/**
 * The footer: rows per page, the "Showing x-y of z" text, the page jump and the pager. Memoised: sorting leaves
 * every prop unchanged, and re-rendering the pager's shared-layout pill would make Motion re-measure the page.
 */
export const TableFooter = memo(function TableFooter({
  labels,
  caption,
  pagination,
  setPagination,
  pageSizeOptions,
  rowsPerPageId,
  initialLoading,
  from,
  to,
  total,
  page,
  pageCount,
  cards,
}: {
  labels: DataTableLabels;
  caption: string;
  pagination: DataTablePagination;
  setPagination: (update: DataTablePagination | ((prev: DataTablePagination) => DataTablePagination)) => void;
  pageSizeOptions: number[];
  rowsPerPageId: string;
  initialLoading: boolean;
  from: number;
  to: number;
  total: number;
  page: number;
  pageCount: number;
  cards: boolean;
}) {
  return (
    <div
      data-slot="data-table-pagination"
      className="flex flex-wrap items-center justify-center gap-x-6 gap-y-3 border-t border-sheen-border px-3 py-3 text-sm sm:justify-between sm:px-4"
    >
      <div className="flex items-center gap-2.5">
        <span id={rowsPerPageId} className="whitespace-nowrap text-sheen-fg-muted">
          {labels.rowsPerPage}
        </span>
        <Select
          aria-labelledby={rowsPerPageId}
          className="w-auto"
          triggerClassName="min-w-20"
          value={String(pagination.pageSize)}
          onValueChange={(v) => {
            const size = Number(v);
            if (!size) return;
            // Keep the first visible row in view when the page size changes.
            setPagination((p) => ({ pageSize: size, pageIndex: Math.floor((p.pageIndex * p.pageSize) / size) }));
          }}
          items={pageSizeOptions.map((n) => ({ value: String(n), label: String(n) }))}
        />
      </div>
      <p className="whitespace-nowrap text-sheen-fg-muted tabular-nums">
        {initialLoading ? labels.loading : labels.showing(from, to, total)}
      </p>
      <div className="flex flex-wrap items-center justify-center gap-x-4 gap-y-2">
        {pageCount > 3 && !cards && (
          <PageJump
            label={labels.goToPage}
            page={page}
            pageCount={pageCount}
            onJump={(p) => setPagination((s) => ({ ...s, pageIndex: p - 1 }))}
          />
        )}
        <Pagination
          page={page}
          pageCount={pageCount}
          onPageChange={(p) => setPagination((s) => ({ ...s, pageIndex: p - 1 }))}
          siblingCount={1}
          size="md"
          disabled={initialLoading}
          labels={{ ...labels.pagination, pageOf: labels.pageOf }}
          aria-label={`${caption}: ${labels.pagination.nav ?? "pagination"}`}
        />
      </div>
    </div>
  );
});

/** A go-to-page number box next to the pager (hidden on phones, which already show the page count between the arrows). */
export function PageJump({
  label,
  page,
  pageCount,
  onJump,
}: {
  label: string;
  page: number;
  pageCount: number;
  onJump: (page: number) => void;
}) {
  const [draft, setDraft] = useState("");
  const labelId = useId();
  const commit = () => {
    const n = Number.parseInt(draft, 10);
    if (Number.isFinite(n)) onJump(Math.min(Math.max(1, n), pageCount));
    setDraft("");
  };
  return (
    // Phones already get "Page x of y" between the arrows.
    <div className="flex items-center gap-2 max-sm:hidden">
      <span id={labelId} className="whitespace-nowrap text-sheen-fg-muted">
        {label}
      </span>
      <Input
        aria-labelledby={labelId}
        type="number"
        inputMode="numeric"
        min={1}
        max={pageCount}
        placeholder={String(page)}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter") commit();
        }}
        onBlur={() => draft && commit()}
        // Wide enough that the input itself (not just its padding) is a 44px target on touch.
        className="w-20"
        inputClassName="any-pointer-coarse:h-11 text-center tabular-nums [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
      />
    </div>
  );
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState, type RefObject } from "react";

/** Rows rendered above and below the visible ones, so a fast scroll never shows blank space. */
const OVERSCAN = 8;
/** Page length from which a table with a bounded height renders only the rows in view (`virtualize` "auto"). */
export const VIRTUALIZE_FROM = 50;

/** The slice of rows to render and the space the rest of them take up. */
export type RowWindow = {
  start: number;
  end: number;
  padTop: number;
  padBottom: number;
};

/**
 * Measured heights: `base` is the height every row not measured yet is assumed to have, `rows` and `details` are by
 * row id. `base` is set once, from the first plain row that renders, and never again: moving it on every later
 * measurement re-priced all the unmeasured rows and the scroll height drifted by thousands of pixels.
 */
type Sizes = { base: number; locked: boolean; rows: Map<string, number>; details: Map<string, number> };

/** What a rendered row reports about its size (`row` is the row itself, `detail` its expanded panel). */
export type ReportRowSize = (rowId: string, part: "row" | "detail", height: number) => void;

/**
 * Row windowing for a table whose scroll area has a bounded height: only the rows in view (plus a few more) are
 * rendered, and two spacer rows stand in for the others. Rows are measured as they render (an expanded panel
 * counts toward its row), and rows not seen yet take one stable estimate (the first row measured). When a row
 * above the viewport turns out taller or shorter than assumed, the scroll position moves by the difference, so
 * what you are looking at stays where it is. Scroll position is read from
 * the scroll area, never from `window`.
 *
 * Accessibility: Rows outside the window are not in the DOM, so Tab and find-in-page skip them; the table sets `aria-rowcount` and each row `aria-rowindex`.
 *
 * @internal DataTable's own windowing hook.
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useRowWindow } from "./row-window";
 *
 * export function Rows({ ids }: { ids: string[] }) {
 *   const scroller = useRef<HTMLDivElement>(null);
 *   const { window } = useRowWindow(scroller, ids, true, 52);
 *   return <div ref={scroller}>{window ? `${window.start} to ${window.end}` : "all rows"}</div>;
 * }
 * ```
 *
 * @param scrollRef - The scroll area.
 * @param ids - Ids of the rows on the page, in order.
 * @param enabled - Window the rows (otherwise `null`: render them all).
 * @param estimate - Row height in px used until a row has been measured.
 * @returns The window (`null` when every row renders) and the callback rendered rows report their size to.
 * @see /components/data-table
 */
export function useRowWindow(
  scrollRef: RefObject<HTMLElement | null>,
  ids: readonly string[],
  enabled: boolean,
  estimate: number,
): { window: RowWindow | null; report: ReportRowSize } {
  const [range, setRange] = useState({ top: 0, height: 0 });
  const [sizes, setSizes] = useState<Sizes>({ base: estimate, locked: false, rows: new Map(), details: new Map() });
  const sizesRef = useRef(sizes);
  // Height change of the rows above the first visible one, applied to scrollTop after the render that uses it.
  const anchorDelta = useRef(0);
  const idsRef = useRef(ids);
  useLayoutEffect(() => {
    idsRef.current = ids;
  }, [ids]);
  // Sizes reported since the last frame; applied together, so a batch of rows re-renders the table once.
  const buffer = useRef<[string, "row" | "detail", number][]>([]);
  const frame = useRef(0);
  const pending = useRef(0);

  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (!enabled || !el) return;
    const read = () => {
      frame.current = 0;
      setRange((prev) =>
        prev.top === el.scrollTop && prev.height === el.clientHeight
          ? prev
          : { top: el.scrollTop, height: el.clientHeight },
      );
    };
    const schedule = () => {
      if (!frame.current) frame.current = requestAnimationFrame(read);
    };
    read();
    el.addEventListener("scroll", schedule, { passive: true });
    const observer = new ResizeObserver(schedule);
    observer.observe(el);
    return () => {
      el.removeEventListener("scroll", schedule);
      observer.disconnect();
      if (frame.current) cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, [scrollRef, enabled]);

  const report = useCallback<ReportRowSize>(
    (rowId, part, height) => {
      buffer.current.push([rowId, part, height]);
      if (pending.current) return;
      pending.current = requestAnimationFrame(() => {
        pending.current = 0;
        const batch = buffer.current;
        buffer.current = [];
        const prev = sizesRef.current;
        const rows = new Map(prev.rows);
        const details = new Map(prev.details);
        let { base, locked } = prev;
        let changed = false;
        let delta = 0;
        // Index of the first row in view, under the sizes as they were before this batch.
        const top = scrollRef.current?.scrollTop ?? 0;
        let firstIndex = 0;
        for (let offset = 0; firstIndex < idsRef.current.length - 1; firstIndex += 1) {
          const id = idsRef.current[firstIndex] ?? "";
          offset += (prev.rows.get(id) ?? prev.base) + (prev.details.get(id) ?? 0);
          if (offset > top) break;
        }
        for (const [id, kind, h] of batch) {
          const map = kind === "row" ? rows : details;
          const before = map.get(id);
          if (before !== undefined && Math.abs(before - h) < 0.5) continue;
          if (kind === "row" && h > 0 && !locked && !details.get(id)) {
            base = h;
            locked = true;
          }
          map.set(id, h);
          changed = true;
          // Rows above the visible one: remember how much their height moved.
          const index = idsRef.current.indexOf(id);
          if (index >= 0 && index < firstIndex) delta += h - (before ?? (kind === "row" ? prev.base : 0));
        }
        if (!changed) return;
        anchorDelta.current += delta;
        sizesRef.current = { base, locked, rows, details };
        setSizes(sizesRef.current);
      });
    },
    [scrollRef],
  );

  // The rows above the viewport changed height: keep the first visible row where it was.
  useLayoutEffect(() => {
    const el = scrollRef.current;
    const delta = anchorDelta.current;
    if (!el || !delta) return;
    anchorDelta.current = 0;
    el.scrollTop += delta;
  }, [sizes, scrollRef]);

  if (!enabled || ids.length === 0) return { window: null, report };
  const { base, rows, details } = sizes;
  const idAt = (i: number) => ids[i] ?? "";
  const heightOf = (id: string) => (rows.get(id) ?? base) + (details.get(id) ?? 0);
  const bottom = range.top + (range.height || base * 12);
  let offset = 0;
  let first = 0;
  while (first < ids.length - 1 && offset + heightOf(idAt(first)) <= range.top) {
    offset += heightOf(idAt(first));
    first += 1;
  }
  let last = first;
  let reach = offset;
  while (last < ids.length && reach < bottom) {
    reach += heightOf(idAt(last));
    last += 1;
  }
  const start = Math.max(0, first - OVERSCAN);
  const end = Math.min(ids.length, last + OVERSCAN);
  let padTop = 0;
  let padBottom = 0;
  for (let i = 0; i < start; i += 1) padTop += heightOf(idAt(i));
  for (let i = end; i < ids.length; i += 1) padBottom += heightOf(idAt(i));
  return { window: { start, end, padTop, padBottom }, report };
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { Fragment, memo, useLayoutEffect, useMemo, useRef, type ReactNode } from "react";
import type { RowData } from "@tanstack/react-table";

import { cn } from "../lib/cn";
import { useRowReorder } from "../motion/reorder";
import { duration, ease } from "../motion/tokens";
import { Checkbox } from "../checkbox/checkbox";
import { RowActionsMenu } from "./column-menu";
import { ChevronRightIcon } from "./icons";
import type { ReportRowSize, RowWindow } from "./row-window";
import { Skeleton } from "./states";
import {
  alignClass,
  cssLength,
  iconButton,
  pinShadow,
  pinShadowEnd,
  pinStyle,
  preventShiftSelect,
  tdBase,
  type DtRow,
  type GridEnv,
  SELECT_W,
} from "./shared";
import type { DataTableColumn, DataTableRowAction, DataTableRowSelection } from "./types";

/** Everything the body rows and the card list need on top of the shared grid environment. */
export type RowsProps<TData extends RowData> = {
  env: GridEnv<TData>;
  rows: DtRow<TData>[];
  rowSelection: DataTableRowSelection;
  expanded: Record<string, boolean>;
  toggleExpanded: (rowId: string) => void;
  toggleRow: (index: number, rowId: string, on: boolean, shift: boolean) => void;
  rowLabel: (row: TData, index: number) => string;
  renderCell: (col: DataTableColumn<TData>, row: TData, rowId: string) => ReactNode;
  actionsFor: (row: TData) => DataTableRowAction<TData>[];
  focusRowActions: (index: number) => void;
  /** Id prefix of the detail rows (the table's `useId`). */
  uid: string;
  reduced: boolean;
  /** Slide rows to their new place when the order changes (position-only FLIP). */
  animateRows?: boolean;
  /** Render only these rows (row windowing); `null` renders them all. */
  rowWindow?: RowWindow | null;
  /** Rendered rows report their height here (the windowing spacers are sized from it). */
  reportRowSize?: ReportRowSize;
};

/** The placeholder rows shown while the first page loads (about a real row's height, so rows landing don't push the footer around). */
export function SkeletonRows<TData extends RowData>({ env, pageSize }: { env: GridEnv<TData>; pageSize: number }) {
  const { colCount, enableSelection, cellPad, compact } = env;
  return Array.from({ length: Math.min(pageSize, 20) }, (_, r) => (
    <tr key={`skeleton-${r}`} aria-hidden>
      {Array.from({ length: colCount }, (_, c) => (
        // Roughly a real row's height, so rows landing don't push the footer around.
        <td key={c} className={cn("border-b border-sheen-border", cellPad, compact ? "h-10" : "h-[3.25rem]")}>
          <Skeleton
            className={cn(["w-3/4", "w-1/2", "w-2/3", "w-5/6"][(r + c) % 4], c === 0 && enableSelection && "w-5")}
          />
        </td>
      ))}
    </tr>
  ));
}

/** How many rows (from the top of the page) slide to their new place on a sort; the rest just swap. */
const ANIMATED_ROWS = 24;

/** What a body row's cells read from the grid environment (memoised, so an unchanged environment lets a row skip rendering). */
type RowEnv<TData extends RowData> = Pick<
  GridEnv<TData>,
  | "labels"
  | "enableSelection"
  | "renderExpanded"
  | "hasActions"
  | "compact"
  | "cellPad"
  | "pinStartCols"
  | "pinFirst"
  | "firstLeft"
  | "lastPinned"
  | "pinCap"
  | "pinnedBg"
  | "visibleColumns"
  | "rowMenu"
> & { renderCell: RowsProps<TData>["renderCell"]; actionsFor: RowsProps<TData>["actionsFor"] };

/** Row handlers keyed by row id, with a stable identity (they read the latest props), so they never invalidate a memoised row. */
type RowFns = {
  toggleRow: (rowId: string, on: boolean, shift: boolean) => void;
  toggleExpanded: (rowId: string) => void;
  focusRowActions: (rowId: string) => void;
};

type RowCellsProps<TData extends RowData> = {
  row: DtRow<TData>;
  selected: boolean;
  isExpanded: boolean;
  label: string;
  detailId: string;
  rowEnv: RowEnv<TData>;
  fns: RowFns;
};

/**
 * The cells of one body row. Memoised: sorting only moves rows, so a row whose data, selection, expansion
 * and environment are unchanged is not rendered again (the `motion.tr` around it still is, which keeps the
 * layout animation measuring every row).
 */
const RowCells = memo(function RowCells<TData extends RowData>({
  row,
  selected,
  isExpanded,
  label,
  detailId,
  rowEnv,
  fns,
}: RowCellsProps<TData>) {
  const {
    labels,
    enableSelection,
    renderExpanded,
    hasActions,
    compact,
    cellPad,
    pinStartCols,
    pinFirst,
    firstLeft,
    lastPinned,
    pinCap,
    pinnedBg,
    visibleColumns,
    rowMenu,
    renderCell,
    actionsFor,
  } = rowEnv;
  const original = row.original;
  const rowId = row.id;
  return (
    <>
      {enableSelection && (
        <td
          style={pinStartCols ? pinStyle(0) : undefined}
          className={cn(
            "ps-4 pe-0",
            tdBase,
            pinStartCols && ["sticky z-[1]", pinnedBg],
            lastPinned === "select" && pinShadow,
            compact ? "py-1.5" : "py-3",
          )}
        >
          <Checkbox
            aria-label={labels.selectRow(label)}
            checked={selected}
            onMouseDown={preventShiftSelect}
            onCheckedChange={(on, details) =>
              fns.toggleRow(rowId, on, Boolean((details.event as MouseEvent | undefined)?.shiftKey))
            }
          />
        </td>
      )}
      {renderExpanded && (
        <td
          style={pinStartCols ? pinStyle(enableSelection ? `${SELECT_W}rem` : 0) : undefined}
          className={cn(
            "px-0",
            tdBase,
            pinStartCols && ["sticky z-[1]", pinnedBg],
            lastPinned === "expand" && pinShadow,
            compact ? "py-0.5" : "py-1.5",
          )}
        >
          <button
            type="button"
            aria-expanded={isExpanded}
            aria-controls={isExpanded ? detailId : undefined}
            aria-label={isExpanded ? labels.collapseRow(label) : labels.expandRow(label)}
            onClick={() => fns.toggleExpanded(rowId)}
            className={iconButton}
          >
            <ChevronRightIcon
              className={cn(
                "rtl:-scale-x-100",
                isExpanded && "rotate-90 rtl:rotate-[-90deg]",
                "motion-ok:transition-transform motion-ok:duration-(--sheen-duration-base) motion-ok:ease-sheen-out",
              )}
            />
          </button>
        </td>
      )}
      {/* From the grid's visible columns, the same list the header maps: they are part of the memoised environment, so a
          column shown or hidden re-renders the row (a cell list read from the row object stayed as it was first computed). */}
      {visibleColumns.map((col, i) => {
        const pinned = pinFirst && i === 0;
        const capped = pinned && pinCap !== undefined;
        const content = renderCell(col, original, rowId);
        return (
          <td
            key={col.id}
            style={{
              ...(pinned ? pinStyle(`${firstLeft}rem`) : {}),
              maxWidth: col.wrap ? cssLength(col.width) : undefined,
              minWidth: col.wrap ? cssLength(col.minWidth ?? col.width) : undefined,
              ...(capped ? { "--dt-pin-cap": pinCap } : {}),
            }}
            className={cn(
              tdBase,
              cellPad,
              "text-sheen-fg",
              col.wrap ? "whitespace-normal" : "whitespace-nowrap",
              alignClass(col),
              pinned && ["sticky z-[1]", pinnedBg, pinShadow],
              capped && "max-sm:min-w-[min(var(--dt-pin-cap),7.5rem)]! max-sm:max-w-(--dt-pin-cap)",
              col.cellClassName,
            )}
          >
            {capped ? (
              // Capped on phones (a `max-sm:` rule, so the prerendered row is as tall as the hydrated one); the full text
              // stays in the DOM for screen readers.
              <div className="max-sm:max-w-(--dt-pin-cap) max-sm:overflow-clip max-sm:text-ellipsis max-sm:whitespace-normal max-sm:[overflow-clip-margin:4px] max-sm:[overflow-wrap:anywhere]">
                {content}
              </div>
            ) : (
              content
            )}
          </td>
        );
      })}
      {hasActions && (
        <td
          style={{ insetInlineEnd: 0 }}
          className={cn(
            "sticky z-[1] px-2",
            tdBase,
            "group-data-more-end/dt:bg-sheen-surface",
            pinShadowEnd,
            compact ? "py-0.5" : "py-1.5",
          )}
        >
          <RowActionsMenu
            handle={rowMenu}
            label={labels.rowActions(label)}
            hasActions={actionsFor(original).length > 0}
            row={original}
            onFocusLost={() => fns.focusRowActions(rowId)}
          />
        </td>
      )}
    </>
  );
}) as <TData extends RowData>(props: RowCellsProps<TData>) => ReactNode;

/** The table body rows: select checkbox, expand chevron, the cells and the row actions, plus the animated detail row. */
export function BodyRows<TData extends RowData>({
  env,
  rows,
  rowSelection,
  expanded,
  toggleExpanded,
  toggleRow,
  rowLabel,
  renderCell,
  actionsFor,
  focusRowActions,
  uid,
  reduced,
  animateRows = true,
  rowWindow = null,
  reportRowSize,
  edgesWidth,
}: RowsProps<TData> & {
  /** The scroller's visible width, so the detail panel stays in view while the table scrolls sideways. */ edgesWidth: number;
}) {
  const {
    labels,
    enableSelection,
    renderExpanded,
    hasActions,
    compact,
    cellPad,
    pinStartCols,
    pinFirst,
    firstLeft,
    lastPinned,
    pinCap,
    pinnedBg,
    colCount,
    visibleColumns,
    rowMenu,
  } = env;
  const edges = { width: edgesWidth };
  const reorder = useRowReorder();
  // Only the first rows are slid into place: measuring every row of a long page for the layout animation is
  // what made a 100-row sort a long task, and rows far down the page are off-screen when the order changes.
  const still = { layout: false as const };
  // Handlers read the latest props through a ref, so their identity never changes and never re-renders a row.
  const latest = useRef({ rows, toggleRow, toggleExpanded, focusRowActions });
  useLayoutEffect(() => {
    latest.current = { rows, toggleRow, toggleExpanded, focusRowActions };
  });
  const fns = useMemo<RowFns>(() => {
    const indexOf = (rowId: string) => latest.current.rows.findIndex((r) => r.id === rowId);
    return {
      toggleRow: (rowId, on, shift) => latest.current.toggleRow(indexOf(rowId), rowId, on, shift),
      toggleExpanded: (rowId) => latest.current.toggleExpanded(rowId),
      focusRowActions: (rowId) => latest.current.focusRowActions(indexOf(rowId)),
    };
  }, []);
  const rowEnv = useMemo<RowEnv<TData>>(
    () => ({
      labels,
      enableSelection,
      renderExpanded,
      hasActions,
      compact,
      cellPad,
      pinStartCols,
      pinFirst,
      firstLeft,
      lastPinned,
      pinCap,
      pinnedBg,
      visibleColumns,
      rowMenu,
      renderCell,
      actionsFor,
    }),
    [
      labels,
      enableSelection,
      renderExpanded,
      hasActions,
      compact,
      cellPad,
      pinStartCols,
      pinFirst,
      firstLeft,
      lastPinned,
      pinCap,
      pinnedBg,
      visibleColumns,
      rowMenu,
      renderCell,
      actionsFor,
    ],
  );
  const firstRow = useRef<HTMLTableRowElement>(null);
  // Measures the rendered rows (and the expanded panels, which add to their row) for the windowing spacers.
  useLayoutEffect(() => {
    const tbody = firstRow.current?.parentElement;
    if (!rowWindow || !reportRowSize || !tbody) return;
    const measure = (tr: Element) => {
      const rowId = tr.getAttribute("data-row-id") ?? tr.getAttribute("data-detail-for");
      if (rowId) {
        reportRowSize(rowId, tr.hasAttribute("data-row-id") ? "row" : "detail", tr.getBoundingClientRect().height);
      }
    };
    const observer = new ResizeObserver((entries) => entries.forEach((e) => measure(e.target)));
    for (const tr of Array.from(tbody.querySelectorAll("tr[data-row-id], tr[data-detail-for]"))) {
      measure(tr);
      observer.observe(tr);
    }
    return () => observer.disconnect();
  });
  const from = rowWindow?.start ?? 0;
  const shown = rowWindow ? rows.slice(rowWindow.start, rowWindow.end) : rows;
  const bodyRows = shown.map((row, at) => {
    const index = from + at;
    const original = row.original;
    const rowId = row.id;
    const selected = Boolean(rowSelection[rowId]);
    const isExpanded = Boolean(expanded[rowId]);
    const label = rowLabel(original, index);
    const detailId = `${uid}-detail-${rowId}`;
    return (
      <Fragment key={rowId}>
        <motion.tr
          ref={at === 0 ? firstRow : undefined}
          aria-rowindex={rowWindow ? index + 2 : undefined}
          data-row-id={rowWindow ? rowId : undefined}
          {...(animateRows && index < ANIMATED_ROWS ? reorder : still)}
          data-slot="data-table-row"
          data-selected={selected || undefined}
          className={cn(
            "transition-colors duration-(--sheen-duration-fast)",
            "hover:[--dt-tint:var(--sheen-hover)] data-selected:[--dt-tint:var(--sheen-accent-soft)]",
          )}
        >
          <RowCells
            row={row}
            selected={selected}
            isExpanded={isExpanded}
            label={label}
            detailId={detailId}
            rowEnv={rowEnv}
            fns={fns}
          />
        </motion.tr>
        {renderExpanded && (
          <AnimatePresence initial={false}>
            {isExpanded && (
              <tr key="detail" id={detailId} data-detail-for={rowWindow ? rowId : undefined}>
                <td colSpan={colCount} className="border-b border-sheen-border p-0">
                  <motion.div
                    initial={{ height: 0 }}
                    animate={{ height: "auto" }}
                    exit={{ height: 0, transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit } }}
                    transition={reduced ? { duration: 0 } : { duration: duration.base, ease: ease.out }}
                    className="overflow-clip"
                  >
                    {/* Pinned to the visible width, so the panel stays in view while the table scrolls sideways. */}
                    <div
                      style={{ width: edges.width || undefined }}
                      className="sticky start-0 bg-sheen-hover/60 px-4 py-4 sm:px-6"
                    >
                      {renderExpanded(original)}
                    </div>
                  </motion.div>
                </td>
              </tr>
            )}
          </AnimatePresence>
        )}
      </Fragment>
    );
  });
  return (
    <>
      {rowWindow && <Spacer height={rowWindow.padTop} colSpan={colCount} />}
      {bodyRows}
      {rowWindow && <Spacer height={rowWindow.padBottom} colSpan={colCount} />}
    </>
  );
}

/** Stands in for the rows that are not rendered (row windowing); hidden from assistive technology. */
function Spacer({ height, colSpan }: { height: number; colSpan: number }) {
  if (height <= 0) return null;
  return (
    <tr aria-hidden data-slot="data-table-spacer">
      <td colSpan={colSpan} style={{ height }} className="p-0" />
    </tr>
  );
}

/** The phone layout: one glass card per row, with the first column as its title and the rest as a label/value list. */
export function CardList<TData extends RowData>({
  env,
  rows,
  rowSelection,
  expanded,
  toggleExpanded,
  toggleRow,
  rowLabel,
  renderCell,
  actionsFor,
  focusRowActions,
  uid,
  reduced,
  captionId,
  caption,
  showCaption,
  initialLoading,
  hasBodyState,
  bodyState,
  pageSize,
}: RowsProps<TData> & {
  captionId: string;
  caption: string;
  showCaption: boolean;
  initialLoading: boolean;
  hasBodyState: boolean;
  bodyState: ReactNode;
  pageSize: number;
}) {
  const {
    labels,
    enableSelection,
    renderExpanded,
    hasActions,
    compact,
    visibleColumns,
    allPageSelected,
    somePageSelected,
    setSelected,
    pageIds,
  } = env;
  return (
    <div className="flex flex-col">
      {/* The table's caption names the card list too. */}
      <p id={captionId} className={showCaption ? "px-4 pt-4 pb-2 text-base font-semibold text-sheen-fg" : "sr-only"}>
        {caption}
      </p>
      {enableSelection && rows.length > 0 && (
        <div className="flex items-center gap-3 border-b border-sheen-border px-4 py-3">
          <Checkbox
            data-dt-anchor=""
            label={labels.selectAllOnPage}
            checked={allPageSelected}
            indeterminate={somePageSelected}
            onCheckedChange={() => setSelected(pageIds, !allPageSelected)}
          />
        </div>
      )}
      {initialLoading ? (
        <ul aria-hidden className="flex flex-col gap-2.5 p-2.5">
          {Array.from({ length: Math.min(pageSize, 5) }, (_, i) => (
            <li key={i} className="glass-1 flex flex-col gap-3 rounded-sheen-lg p-4">
              <Skeleton className="h-4 w-1/2" />
              <Skeleton className="w-3/4" />
              <Skeleton className="w-2/3" />
            </li>
          ))}
        </ul>
      ) : hasBodyState ? (
        bodyState
      ) : (
        <ul aria-labelledby={captionId} className="flex flex-col gap-2.5 p-2.5">
          {rows.map((row, index) => {
            const original = row.original;
            const rowId = row.id;
            const selected = Boolean(rowSelection[rowId]);
            const isExpanded = Boolean(expanded[rowId]);
            const label = rowLabel(original, index);
            const [primary, ...rest] = visibleColumns;
            const detailId = `${uid}-card-detail-${rowId}`;
            return (
              <li
                key={rowId}
                data-selected={selected || undefined}
                className={cn(
                  "glass-1 rounded-sheen-lg",
                  "data-selected:border-sheen-accent-border data-selected:[background-image:linear-gradient(var(--sheen-accent-soft),var(--sheen-accent-soft))]",
                )}
              >
                <div className={cn("flex items-center gap-3", compact ? "px-3 py-2.5" : "px-4 py-3.5")}>
                  {enableSelection && (
                    <Checkbox
                      aria-label={labels.selectRow(label)}
                      checked={selected}
                      onCheckedChange={(on) => toggleRow(index, rowId, on, false)}
                    />
                  )}
                  <div className="min-w-0 flex-1 font-medium">{primary && renderCell(primary, original, rowId)}</div>
                  {hasActions && (
                    <RowActionsMenu
                      handle={env.rowMenu}
                      label={labels.rowActions(label)}
                      hasActions={actionsFor(original).length > 0}
                      row={original}
                      onFocusLost={() => focusRowActions(index)}
                    />
                  )}
                </div>
                <dl
                  className={cn(
                    "grid grid-cols-[minmax(5.5rem,auto)_minmax(0,1fr)] items-center gap-x-4 border-t border-sheen-border text-sm",
                    compact ? "gap-y-1.5 px-3 py-2.5" : "gap-y-2.5 px-4 py-3.5",
                  )}
                >
                  {rest
                    .filter((c) => !c.hideInCards)
                    .map((c) => (
                      <Fragment key={c.id}>
                        <dt className="text-xs text-sheen-fg-muted">{c.header}</dt>
                        <dd className={cn("min-w-0 text-sheen-fg", c.numeric && "tabular-nums")}>
                          {renderCell(c, original, rowId)}
                        </dd>
                      </Fragment>
                    ))}
                </dl>
                {renderExpanded && (
                  <div className="border-t border-sheen-border">
                    <button
                      type="button"
                      aria-expanded={isExpanded}
                      aria-controls={isExpanded ? detailId : undefined}
                      // Short visible text; the row's name is in the accessible name (which starts with it).
                      aria-label={isExpanded ? labels.collapseRow(label) : labels.expandRow(label)}
                      onClick={() => toggleExpanded(rowId)}
                      className="flex min-h-11 w-full items-center gap-2 rounded-b-sheen-lg px-4 text-sm font-medium text-sheen-fg-muted hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus"
                    >
                      <ChevronRightIcon
                        className={cn(
                          "rtl:-scale-x-100",
                          isExpanded && "rotate-90 rtl:rotate-[-90deg]",
                          "motion-ok:transition-transform motion-ok:duration-(--sheen-duration-base)",
                        )}
                      />
                      {isExpanded ? labels.hideDetails : labels.showDetails}
                    </button>
                    <AnimatePresence initial={false}>
                      {isExpanded && (
                        <motion.div
                          key="detail"
                          id={detailId}
                          initial={{ height: 0 }}
                          animate={{ height: "auto" }}
                          exit={{ height: 0, transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit } }}
                          transition={reduced ? { duration: 0 } : { duration: duration.base, ease: ease.out }}
                          className="overflow-clip"
                        >
                          <div className="px-4 pb-4">{renderExpanded(original)}</div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import type { RowData } from "@tanstack/react-table";
import { useEffect, useState, type RefObject } from "react";
import { useLatest } from "../hooks/use-latest";

import { duration, ease, spring } from "../motion/tokens";
import { Button } from "../button/button";
import { CloseIcon, DownloadIcon } from "./icons";
import { linkButton, type DtRow } from "./shared";
import type { DataTableLabels, DataTableProps } from "./types";

/**
 * The strip above the table when every row of the page is selected: offers to select all matching rows, or
 * confirms they are all selected and offers to clear.
 */
export function SelectionBanner<TData extends RowData>({
  labels,
  total,
  pageRowCount,
  selectedMatching,
  matchingRows,
  setSelected,
  clearSelection,
  focusIfLost,
  focusAnchor,
}: {
  labels: DataTableLabels;
  total: number;
  pageRowCount: number;
  selectedMatching: number;
  matchingRows: DtRow<TData>[];
  setSelected: (ids: string[], on: boolean) => void;
  clearSelection: () => void;
  focusIfLost: (pick: () => HTMLElement | null | undefined) => void;
  focusAnchor: () => HTMLElement | null;
}) {
  return (
    <div className="flex flex-wrap items-center justify-center gap-x-2 gap-y-1 border-b border-sheen-border bg-sheen-accent-soft px-4 py-1.5 text-center text-sm">
      {/* Compare with the matching rows only: rows selected earlier may be hidden by a filter now. */}
      {selectedMatching >= total ? (
        <>
          <span>{labels.allSelected(total)}</span>
          <button
            type="button"
            onClick={() => {
              clearSelection();
              focusIfLost(focusAnchor);
            }}
            className={linkButton}
          >
            {labels.clearSelection}
          </button>
        </>
      ) : (
        <>
          <span>{labels.allOnPageSelected(pageRowCount)}</span>
          <button
            type="button"
            onClick={() =>
              setSelected(
                matchingRows.map((r) => r.id),
                true,
              )
            }
            className={linkButton}
          >
            {labels.selectAllMatching(total)}
          </button>
        </>
      )}
    </div>
  );
}

/** The floating bar with the selected count and the bulk actions; it slides up while something is selected. */
export function SelectionBar<TData>({
  barRef,
  count,
  hidden,
  labels,
  reduced,
  onClear,
  onClosedWithFocus,
  onExport,
  actions,
  getRows,
}: {
  barRef: RefObject<HTMLDivElement | null>;
  count: number;
  /** Selected rows the search / filters hide. */
  hidden: number;
  labels: DataTableLabels;
  reduced: boolean;
  onClear: () => void;
  /** The bar is closing while it holds focus (Clear, Delete, …): move focus back into the table. */
  onClosedWithFocus: () => void;
  onExport?: () => void;
  actions: DataTableProps<TData>["bulkActions"] & object;
  getRows: () => TData[];
}) {
  // Keep the last counts while the bar animates out.
  const [shown, setShown] = useState({ count, hidden });
  if (count > 0 && (shown.count !== count || shown.hidden !== hidden)) setShown({ count, hidden });
  const onClosedRef = useLatest(onClosedWithFocus);
  useEffect(() => {
    if (count === 0 && barRef.current?.contains(document.activeElement)) onClosedRef.current();
  }, [count, barRef, onClosedRef]);
  return (
    <AnimatePresence initial={false}>
      {count > 0 && (
        // The slot reserves room (height only, never faded: the bar inside is glass).
        <motion.div
          key="selection-slot"
          initial={{ height: 0 }}
          animate={{ height: "auto" }}
          exit={{ height: 0 }}
          transition={reduced ? { duration: 0 } : { duration: duration.base, ease: ease.out }}
          className="pointer-events-none sticky bottom-0 z-30 -mt-3"
        >
          <div className="flex justify-center px-2 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
            <motion.div
              ref={barRef}
              role="region"
              aria-label={labels.bulkActions}
              initial={reduced ? { opacity: 0 } : { opacity: 0, y: 24, scale: 0.96 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={
                reduced
                  ? { opacity: 0, transition: { duration: duration.exit } }
                  : { opacity: 0, y: 16, scale: 0.98, transition: { duration: duration.exit, ease: ease.exit } }
              }
              transition={reduced ? { duration: duration.fast } : spring.gentle}
              className="glass-3 pointer-events-auto flex max-w-full flex-wrap items-center justify-center gap-1 rounded-sheen-xl p-1.5 ps-4 shadow-[0_18px_40px_-16px_color-mix(in_oklab,var(--sheen-fg)_40%,transparent)] sm:flex-nowrap sm:rounded-sheen-full"
            >
              <span className="me-1 flex flex-col text-sm leading-tight font-semibold whitespace-nowrap tabular-nums">
                {labels.selectedCount(shown.count)}
                {shown.hidden > 0 && (
                  <span className="text-2xs font-medium text-sheen-fg-muted">
                    {labels.hiddenSelected(shown.hidden)}
                  </span>
                )}
              </span>
              <span aria-hidden className="mx-1 h-5 w-px bg-sheen-border max-sm:hidden" />
              {onExport && (
                // Visible "Export", accessible name "Export selected" (distinct from the toolbar's Export).
                // Icon-only on phones so the bar stays on one row at 320px.
                <Button
                  variant="ghost"
                  size="sm"
                  leading={<DownloadIcon />}
                  onClick={onExport}
                  aria-label={labels.exportSelected}
                >
                  <span className="max-sm:sr-only">{labels.exportCsv}</span>
                </Button>
              )}
              {actions.map((action) => (
                <Button
                  key={action.label}
                  variant={action.tone === "danger" ? "danger" : "ghost"}
                  size="sm"
                  leading={action.icon}
                  onClick={() => action.onSelect(getRows(), onClear)}
                >
                  {action.label}
                </Button>
              ))}
              <Button
                variant="ghost"
                size="sm"
                onClick={onClear}
                aria-label={labels.clearSelection}
                className="size-8 px-0"
              >
                <CloseIcon />
              </Button>
            </motion.div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import {
  columnFacetingFeature,
  columnFilteringFeature,
  columnVisibilityFeature,
  createFacetedRowModel,
  createFacetedUniqueValues,
  createFilteredRowModel,
  createPaginatedRowModel,
  createSortedRowModel,
  globalFilteringFeature,
  rowPaginationFeature,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_basic,
  sortFn_datetime,
  sortFn_text,
  tableFeatures,
  type ReactTable,
  type Row,
  type RowData,
} from "@tanstack/react-table";

import { cn } from "../lib/cn";
import type { RowMenuHandle } from "./column-menu";
import type { DataTableColumn, DataTableLabels, DataTableProps } from "./types";

/** The table features (and their row models), created once at module scope so they stay stable across renders. */
export const features = tableFeatures({
  columnVisibilityFeature,
  columnFilteringFeature,
  globalFilteringFeature,
  columnFacetingFeature,
  rowSortingFeature,
  rowPaginationFeature,
  filteredRowModel: createFilteredRowModel(),
  facetedRowModel: createFacetedRowModel(),
  facetedUniqueValues: createFacetedUniqueValues(),
  sortedRowModel: createSortedRowModel(),
  paginatedRowModel: createPaginatedRowModel(),
  sortFns: { alphanumeric: sortFn_alphanumeric, text: sortFn_text, basic: sortFn_basic, datetime: sortFn_datetime },
});

/** The table instance DataTable builds (its feature set is fixed). */
export type DtTable<TData extends RowData> = ReactTable<typeof features, TData>;
/** One row of that table. */
export type DtRow<TData extends RowData> = Row<typeof features, TData>;

/** The two members of a TanStack row the filters read. */
export type RowLike<TData> = { original: TData; getValue: (columnId: string) => unknown };

/** A state setter that takes a value or an updater, like the one `useControllable` returns. */
export type Setter<T> = (update: T | ((prev: T) => T)) => void;

/** Faceted filter: keep rows whose value is one of the picked values. */
export const inSetFilter = Object.assign(
  (row: RowLike<unknown>, columnId: string, filterValue: unknown) =>
    !Array.isArray(filterValue) || filterValue.length === 0 || filterValue.includes(stringify(row.getValue(columnId))),
  { autoRemove: (value: unknown) => !Array.isArray(value) || value.length === 0 },
);

/** A stable empty list, so a default prop does not change identity on every render. */
export const EMPTY: never[] = [];
/** The page sizes offered when `pageSizeOptions` is not set. */
export const PAGE_SIZES = [10, 20, 50, 100];
/** Width of the selection checkbox column, in rem. */
export const SELECT_W = 3; // rem
/** Width of the expand-chevron column, in rem. */
export const EXPAND_W = 2.75; // rem

/** Any cell value as text: dates as ISO strings, arrays joined, `null` and `undefined` empty. */
export function stringify(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (value instanceof Date) return value.toISOString();
  if (Array.isArray(value)) return value.map(stringify).join(", ");
  // eslint-disable-next-line @typescript-eslint/no-base-to-string -- arbitrary cell data: a custom toString() is honoured, plain objects fall back to the default
  return String(value);
}

/** A column width as a CSS length: numbers are pixels. */
export const cssLength = (v: number | string | undefined) => (typeof v === "number" ? `${v}px` : v);

/** The global filter as TanStack sees it: a new object whenever the query or the searched columns change. */
export type SearchState = { folded: string; columns: string };

/** A state value or an updater function, the two forms TanStack hands to its change callbacks. */
export type Updater<T> = T | ((prev: T) => T);

/** The raw value of a column for a row: its accessor function, else the `accessorKey` (or `id`) property. */
export function readValue<TData>(col: DataTableColumn<TData>, row: TData): unknown {
  return col.accessorFn ? col.accessorFn(row) : (row as Record<string, unknown>)[col.accessorKey ?? col.id];
}

/** Text alignment classes of a column. */
export const alignClass = <TData>(col: DataTableColumn<TData>) => {
  const align = col.align ?? (col.numeric ? "right" : "left");
  // Explicit start alignment: browsers centre <th> by default.
  return cn(
    align === "right" ? "text-end" : align === "center" ? "text-center" : "text-start",
    col.numeric && "tabular-nums",
  );
};

/** Sticky offsets are logical (inset-inline-*), so pinning works in RTL too. */
export const pinStyle = (offset: string | number) => ({ insetInlineStart: offset });

/** Everything the header, the rows and the card list share: which columns exist, which are pinned, and the density. */
export type GridEnv<TData extends RowData> = {
  labels: DataTableLabels;
  enableSelection: boolean;
  renderExpanded: DataTableProps<TData>["renderExpanded"];
  hasActions: boolean;
  compact: boolean;
  cellPad: string;
  pinStartCols: boolean;
  pinFirst: boolean;
  firstLeft: number;
  /** The start-pinned column that carries the edge shadow. */
  lastPinned: "first" | "expand" | "select" | null;
  pinCap: string | undefined;
  pinnedBg: string;
  colCount: number;
  visibleColumns: DataTableColumn<TData>[];
  colById: Map<string, DataTableColumn<TData>>;
  pageIds: string[];
  allPageSelected: boolean;
  somePageSelected: boolean;
  setSelected: (ids: string[], on: boolean) => void;
  /** Links each row's "..." button to the table's one shared actions menu. */
  rowMenu: RowMenuHandle<TData>;
};

/** Shift-click (range select, multi-sort) would otherwise also select the page's text. */
export const preventShiftSelect = (event: { shiftKey: boolean; preventDefault: () => void }) => {
  if (event.shiftKey) event.preventDefault();
};

/* ---------- shared class strings ---------- */

/** Classes of a body cell: the bottom border, the row tint (hover or selected) over any pinned background, and no border on the last row. */
export const tdBase = cn(
  "border-b border-sheen-border align-middle",
  // Row tint (hover / selected) layered over any pinned background.
  "[background-image:linear-gradient(var(--dt-tint,transparent),var(--dt-tint,transparent))]",
  "[tr:last-child>&]:border-b-0",
