/** A shimmering placeholder bar for loading rows and cards. */
export function Skeleton({ className }: { className?: string }) {
  return (
    // A visible bar (not a hairline) with a clear sweep of light: a loading table must look like one.
    <span className={cn("relative block h-3.5 overflow-hidden rounded-sheen-full bg-sheen-fg/[0.12]", className)}>
      <span className="absolute inset-y-0 start-0 w-1/2 bg-gradient-to-r from-transparent via-sheen-fg/[0.22] to-transparent opacity-0 motion-ok:animate-[sheen-shine_var(--sheen-duration-loop-steady)_var(--sheen-ease-in-out)_infinite] motion-ok:opacity-100" />
    </span>
  );
}

/** A centred icon, title, description and actions: the empty and error states of the table body. */
export function StateBlock({
  icon,
  title,
  description,
  actions,
  tone = "neutral",
  role,
}: {
  icon: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  actions?: ReactNode;
  tone?: "neutral" | "danger";
  role?: "alert";
}) {
  return (
    <div role={role} className="flex flex-col items-center gap-3 px-6 py-14 text-center">
      <span
        className={cn(
          "flex size-11 items-center justify-center rounded-sheen-full border",
          tone === "danger"
            ? "border-sheen-danger-text/25 bg-sheen-danger-soft text-sheen-danger-text"
            : "border-sheen-accent-border bg-sheen-accent-soft text-sheen-accent",
        )}
      >
        {icon}
      </span>
      <div className="flex max-w-sm flex-col gap-1">
        <p className="text-base font-semibold text-balance text-sheen-fg">{title}</p>
        {description && <p className="text-sm text-pretty text-sheen-fg-muted">{description}</p>}
      </div>
      {actions && <div className="mt-1 flex flex-wrap justify-center gap-2">{actions}</div>}
    </div>
  );
}

/** The error state that replaces the body when a request failed and there are no rows to keep. */
export function ErrorBlock({
  labels,
  errorText,
  retry,
  loading,
}: {
  labels: DataTableLabels;
  errorText: ReactNode;
  retry: (() => void) | undefined;
  loading: boolean;
}) {
  // A real inline Alert (danger tone, announced at once) with a retry action: impossible to miss in an empty table body.
  return (
    <div className="p-4 sm:p-6">
      <Alert
        tone="danger"
        title={labels.errorTitle}
        action={
          retry && (
            <Button variant="glass" size="sm" onClick={retry} loading={loading}>
              {labels.retry}
            </Button>
          )
        }
      >
        {errorText}
      </Alert>
    </div>
  );
}

/** The empty state: no rows at all, no rows for the search, or none for the filters (with the buttons that undo them). */
export function EmptyBlock({
  labels,
  query,
  filtersActive,
  clearSearch,
  clearFilters,
}: {
  labels: DataTableLabels;
  query: string;
  filtersActive: boolean;
  clearSearch: () => void;
  clearFilters: () => void;
}) {
  return query || filtersActive ? (
    <StateBlock
      icon={<EmptyIcon className="size-5" />}
      title={query ? labels.emptyForQuery(query) : labels.emptyFiltered}
      description={labels.emptyFilteredDescription}
      actions={
        <>
          {query && (
            <Button variant="glass" size="sm" onClick={clearSearch}>
              {labels.clearSearch}
            </Button>
          )}
          {filtersActive && (
            <Button variant="glass" size="sm" onClick={clearFilters}>
              {labels.clearFilters}
            </Button>
          )}
        </>
      }
    />
  ) : (
    <StateBlock icon={<EmptyIcon className="size-5" />} title={labels.empty} description={labels.emptyDescription} />
  );
}

/**
 * Refetch error: the previous rows stay exactly where they are (under the veil) and the alert takes an in-flow slot
 * BELOW them, above the pagination. Nothing above it moves: an in-flow banner above the table pushed the rows down
 * 66-74px when the request failed (an unexpected layout shift, and a page scroll wherever scroll anchoring kicked in).
 * It overlaps nothing, so no focused row control is ever hidden behind it (WCAG 2.4.11) and a one-row table can't be
 * overrun. Opaque surface + tint as an image: text stays >= 4.5:1, and forced colours (which drop background images)
 * map the surface to an opaque Canvas.
 */
export function StaleErrorAlert({
  labels,
  errorText,
  retry,
  loading,
}: {
  labels: DataTableLabels;
  errorText: ReactNode;
  retry: (() => void) | undefined;
  loading: boolean;
}) {
  return (
    <div className="border-t border-sheen-border p-2 sm:p-3">
      <Alert
        tone="danger"
        title={labels.errorTitle}
        action={
          retry && (
            <Button variant="glass" size="sm" onClick={retry} loading={loading}>
              {labels.retry}
            </Button>
          )
        }
      >
        {errorText}
      </Alert>
    </div>
  );
}

/** The "more to scroll this way" fades over the scroll area's edges (only for the table layout). */
export function EdgeFades({
  hasActions,
  lastPinned,
}: {
  hasActions: boolean;
  lastPinned: "first" | "expand" | "select" | null;
}) {
  return (
    <>
      {/* With a pinned actions column, its own edge shadow does this job. */}
      {!hasActions && (
        <span
          aria-hidden
          className={cn(edgeFade, "end-0 bg-gradient-to-l rtl:bg-gradient-to-r", "group-data-more-end/dtw:opacity-100")}
        />
      )}
      {lastPinned === null && (
        <span
          aria-hidden
          className={cn(
            edgeFade,
            "start-0 bg-gradient-to-r rtl:bg-gradient-to-l",
            "group-data-scrolled-x/dtw:opacity-100",
          )}
        />
      )}
    </>
  );
}

/** While a request runs: the veil over the previous rows (refetch or a failed refetch) and the thin progress bar under the header. */
export function LoadingOverlays({
  cards,
  headerHeight,
  loading,
  veil,
}: {
  cards: boolean;
  headerHeight: number;
  loading: boolean;
  veil: boolean;
}) {
  return (
    <>
      {/* Refetch (or a failed refetch): previous rows stay put under a veil; a thin bar runs under the header. */}
      {veil && (
        <span
          aria-hidden
          style={{ top: cards ? 0 : headerHeight }}
          className="pointer-events-none absolute inset-x-0 bottom-0 z-[4] bg-sheen-bg/60 motion-ok:animate-pulse"
        />
      )}
      {loading && (
        <span
          aria-hidden
          style={{ top: cards ? 0 : Math.max(0, headerHeight - 1) }}
          className="pointer-events-none absolute inset-x-0 z-[5] h-1.5 overflow-hidden bg-sheen-accent-soft"
        >
          <span className="sheen-fill block h-full w-full opacity-50 [background-image:var(--sheen-accent-fill)] motion-ok:w-1/3 motion-ok:opacity-100 motion-ok:animate-[sheen-indeterminate_var(--sheen-duration-loop-quick)_var(--sheen-ease-in-out)_infinite]" />
        </span>
      )}
    </>
  );
}

"use client";

import type { ReactNode, RefObject } from "react";

import { cn } from "../lib/cn";
import { Button } from "../button/button";
import { Input } from "../input/input";
import { Select } from "../select/select";
import { ViewMenu } from "./column-menu";
import { CloseIcon, DownloadIcon, PlusCircleIcon, SearchIcon } from "./icons";
import {
  DataMenu,
  DataMenuCheckboxItem,
  DataMenuContent,
  DataMenuGroup,
  DataMenuItem,
  DataMenuLabel,
  DataMenuSeparator,
  DataMenuTrigger,
} from "./menu";
import type { Setter } from "./shared";
import type {
  DataTableColumn,
  DataTableColumnFilters,
  DataTableColumnVisibility,
  DataTableDensity,
  DataTableFilterOption,
  DataTableLabels,
  DataTableSorting,
} from "./types";

/** The toolbar above the table: search, faceted filters, the phone sort select, export and the View menu. */
export function Toolbar<TData>({
  labels,
  toolbarLeft,
  toolbarRight,
  enableSearch,
  enableSorting,
  enableViewOptions,
  canExportAll,
  cards,
  total,
  density,
  setDensity,
  sorting,
  setSorting,
  columns,
  visibleColumns,
  columnVisibility,
  setColumnVisibility,
  searchRef,
  searchInput,
  setSearchInput,
  applySearch,
  clearSearch,
  facetedColumns,
  facetOptions,
  filterValues,
  setFilter,
  runExport,
}: {
  labels: DataTableLabels;
  toolbarLeft: ReactNode;
  toolbarRight: ReactNode;
  enableSearch: boolean;
  enableSorting: boolean;
  enableViewOptions: boolean;
  canExportAll: boolean;
  cards: boolean;
  total: number;
  density: DataTableDensity;
  setDensity: (density: DataTableDensity) => void;
  sorting: DataTableSorting;
  setSorting: Setter<DataTableSorting>;
  columns: DataTableColumn<TData>[];
  visibleColumns: DataTableColumn<TData>[];
  columnVisibility: DataTableColumnVisibility;
  setColumnVisibility: Setter<DataTableColumnVisibility>;
  searchRef: RefObject<HTMLInputElement | null>;
  searchInput: string;
  setSearchInput: (value: string) => void;
  applySearch: (value: string) => void;
  clearSearch: () => void;
  facetedColumns: DataTableColumn<TData>[];
  facetOptions: (col: DataTableColumn<TData>) => DataTableFilterOption[];
  filterValues: (columnId: string) => string[];
  setFilter: (columnId: string, values: string[]) => void;
  runExport: (scope: "filtered" | "selected") => void;
}) {
  const sortableColumns = visibleColumns.filter((c) => enableSorting && c.enableSorting !== false);
  // Short visible options ("Signed up ↓") so the select fits beside Export and View on a phone.
  const sortOption = (text: string, short: string) => (
    <>
      <span aria-hidden>{short}</span>
      <span className="sr-only">{text}</span>
    </>
  );
  const sortSelect = cards && sortableColumns.length > 0 && (
    <Select
      aria-label={labels.sortBy}
      className="w-auto min-w-0 flex-1"
      triggerClassName="min-w-0"
      value={sorting[0] ? `${sorting[0].id}:${sorting[0].desc ? "desc" : "asc"}` : "__none"}
      onValueChange={(v) => {
        if (!v || v === "__none") {
          setSorting([]);
          return;
        }
        const [colId, dir] = v.split(":");
        setSorting([{ id: colId ?? "", desc: dir === "desc" }]);
      }}
      items={[
        { value: "__none", label: labels.sortDefault },
        ...sortableColumns.flatMap((c) => [
          { value: `${c.id}:asc`, label: sortOption(labels.sortOptionAsc(c.header), `${c.header} ↑`) },
          { value: `${c.id}:desc`, label: sortOption(labels.sortOptionDesc(c.header), `${c.header} ↓`) },
        ]),
      ]}
    />
  );

  return (
    <div className="flex flex-wrap items-center gap-2">
      {toolbarLeft}
      {enableSearch && (
        <Input
          ref={searchRef}
          type="search"
          aria-label={labels.searchLabel}
          placeholder={labels.searchPlaceholder}
          value={searchInput}
          onChange={(e) => setSearchInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") applySearch(searchInput);
            if (e.key === "Escape" && searchInput) {
              e.preventDefault();
              clearSearch();
            }
          }}
          autoComplete="off"
          spellCheck={false}
          className="w-full sm:w-64 lg:w-72"
          // 44px tall on touch (the field's border would otherwise leave the input at 42px).
          inputClassName="[&::-webkit-search-cancel-button]:appearance-none any-pointer-coarse:h-11"
          leading={<SearchIcon />}
          trailing={
            searchInput ? (
              <button
                type="button"
                onClick={clearSearch}
                aria-label={labels.clearSearch}
                className="relative -me-1.5 flex size-7 items-center justify-center rounded-sheen-full text-sheen-fg-muted hover:bg-sheen-hover hover:text-sheen-fg focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus any-pointer-coarse:after:absolute any-pointer-coarse:after:size-11"
              >
                <CloseIcon className="size-3.5" />
              </button>
            ) : undefined
          }
        />
      )}
      {facetedColumns.map((col) => (
        <FacetedFilter
          key={col.id}
          title={col.header}
          options={facetOptions(col)}
          selected={filterValues(col.id)}
          onChange={(values) => setFilter(col.id, values)}
          labels={labels}
        />
      ))}
      {/* Cards: the sort select shares one row with Export / View and takes the spare width. */}
      <div className={cn("flex items-center gap-2", sortSelect ? "w-full min-w-0" : "ms-auto flex-wrap")}>
        {sortSelect}
        {toolbarRight}
        {canExportAll && (
          <Button
            variant="glass"
            className="h-11"
            leading={<DownloadIcon />}
            onClick={() => runExport("filtered")}
            disabled={total === 0}
          >
            <span className="max-sm:sr-only">{labels.exportCsv}</span>
          </Button>
        )}
        {enableViewOptions && (
          <ViewMenu
            labels={labels}
            density={density}
            onDensityChange={setDensity}
            columns={columns}
            isVisible={(colId) => columnVisibility[colId] !== false}
            visibleCount={visibleColumns.length}
            onToggle={(colId, on) => {
              setColumnVisibility((v) => ({ ...v, [colId]: on }));
              // A hidden column can't show its sort arrow: drop its sort rather than sort invisibly.
              if (!on && sorting.some((s) => s.id === colId)) setSorting((prev) => prev.filter((s) => s.id !== colId));
            }}
          />
        )}
      </div>
    </div>
  );
}

/** One faceted filter: a menu of checkable options with counts, plus a clear item. */
export function FacetedFilter({
  title,
  options,
  selected,
  onChange,
  labels,
}: {
  title: string;
  options: DataTableFilterOption[];
  selected: string[];
  onChange: (values: string[]) => void;
  labels: DataTableLabels;
}) {
  const set = new Set(selected);
  return (
    <DataMenu>
      <DataMenuTrigger
        render={
          <Button
            data-dt-filter=""
            variant="glass"
            className={cn("h-11 px-3.5", set.size > 0 && "border-sheen-accent-border")}
            aria-label={labels.filterSelected(title, set.size)}
            leading={<PlusCircleIcon className={cn("text-sheen-fg-muted", set.size > 0 && "text-sheen-accent")} />}
          />
        }
      >
        <span className="inline-flex items-center gap-2">
          {title}
          {set.size > 0 && (
            <span className="inline-flex h-5 min-w-5 items-center justify-center rounded-sheen-full bg-sheen-accent-soft px-1.5 text-2xs font-semibold text-sheen-accent tabular-nums">
              {set.size}
            </span>
          )}
        </span>
      </DataMenuTrigger>
      <DataMenuContent className="w-60">
        <DataMenuGroup>
          <DataMenuLabel>{title}</DataMenuLabel>
          {options.map((option) => (
            <DataMenuCheckboxItem
              key={option.value}
              checked={set.has(option.value)}
              onCheckedChange={(on) => {
                const next = new Set(set);
                if (on) next.add(option.value);
                else next.delete(option.value);
                // Keep the option order, not the click order.
                onChange(options.map((o) => o.value).filter((v) => next.has(v)));
              }}
              trailing={
                option.count !== undefined && (
                  <span className="ms-auto ps-3 text-xs text-sheen-fg-muted tabular-nums">
                    <span aria-hidden>{option.count.toLocaleString()}</span>
                    {/* "Owner, 28 rows" rather than "Owner 28". */}
                    <span className="sr-only">, {labels.facetCount(option.count)}</span>
                  </span>
                )
              }
            >
              <span className="flex items-center gap-2">
                {option.icon}
                {option.label}
              </span>
            </DataMenuCheckboxItem>
          ))}
        </DataMenuGroup>
        {set.size > 0 && (
          <>
            <DataMenuSeparator />
            <DataMenuItem onClick={() => onChange([])} className="justify-center text-sheen-fg-muted">
              {labels.clearFilter}
            </DataMenuItem>
          </>
        )}
      </DataMenuContent>
    </DataMenu>
  );
}

/** The removable chips for the active faceted filters, plus a "Clear filters" button. */
export function FilterChips<TData>({
  columnFilters,
  colById,
  labels,
  chipsRef,
  searchRef,
  setFilter,
  clearFilters,
  focusIfLost,
  focusAnchor,
}: {
  columnFilters: DataTableColumnFilters;
  colById: Map<string, DataTableColumn<TData>>;
  labels: DataTableLabels;
  chipsRef: RefObject<HTMLDivElement | null>;
  searchRef: RefObject<HTMLInputElement | null>;
  setFilter: (columnId: string, values: string[]) => void;
  clearFilters: () => void;
  focusIfLost: (pick: () => HTMLElement | null | undefined) => void;
  focusAnchor: () => HTMLElement | null;
}) {
  let chipCount = 0;
  return (
    <div
      ref={chipsRef}
      role="group"
      aria-label={labels.filterChipsLabel}
      className="flex flex-wrap items-center gap-1.5"
    >
      {columnFilters.flatMap((f) => {
        const col = colById.get(f.id);
        if (!col) return [];
        const options = col.filterOptions;
        return f.value.map((value) => {
          const label = options?.find((o) => o.value === value)?.label ?? value;
          const chipIndex = chipCount++;
          return (
            <button
              key={`${f.id}:${value}`}
              type="button"
              data-dt-chip=""
              onClick={() => {
                setFilter(
                  f.id,
                  f.value.filter((v) => v !== value),
                );
                // Focus the chip that took this one's place, else the one before, else the search box.
                focusIfLost(() => {
                  const rest = chipsRef.current?.querySelectorAll<HTMLElement>("[data-dt-chip]");
                  return rest?.[Math.min(chipIndex, rest.length - 1)] ?? searchRef.current ?? focusAnchor();
                });
              }}
              aria-label={labels.removeFilter(col.header, label)}
              className={cn(
                "group/chip relative inline-flex h-8 items-center gap-1.5 rounded-sheen-full border border-sheen-accent-border bg-sheen-accent-soft ps-3 pe-1.5 text-xs font-medium text-sheen-fg",
                "transition-colors hover:bg-sheen-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
                "any-pointer-coarse:after:absolute any-pointer-coarse:after:inset-x-0 any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:h-11 any-pointer-coarse:after:-translate-y-1/2",
              )}
            >
              <span className="text-sheen-fg-muted">{col.header}:</span>
              {label}
              <span
                aria-hidden
                className="flex size-5 items-center justify-center rounded-full group-hover/chip:bg-sheen-hover"
              >
                <CloseIcon className="size-3" />
              </span>
            </button>
          );
        });
      })}
      <Button variant="ghost" size="sm" onClick={clearFilters} className="text-sheen-fg-muted hover:text-sheen-fg">
        {labels.clearFilters}
      </Button>
    </div>
  );
}

import type { ReactNode } from "react";

import type { PaginationLabels } from "../pagination/pagination";

/** Row height: "comfortable" (roomier) or "compact" (more rows on screen). */
export type DataTableDensity = "comfortable" | "compact";
/** Horizontal text alignment of a column. */
export type DataTableAlign = "left" | "center" | "right";

/** Sorting: first entry is the primary sort. */
export type DataTableSorting = { id: string; desc: boolean }[];
/** 0-based page index, like TanStack Table. */
export type DataTablePagination = { pageIndex: number; pageSize: number };
/** Faceted filters: the values kept for each filtered column. */
export type DataTableColumnFilters = { id: string; value: string[] }[];
/** Selected row ids → true. Ids come from `getRowId`, so selection survives paging and sorting. */
export type DataTableRowSelection = Record<string, boolean>;
/** Column id → visible. Missing ids are visible. */
export type DataTableColumnVisibility = Record<string, boolean>;

/** One choice in a column's faceted filter. */
export type DataTableFilterOption = {
  /** The cell value this option matches. */
  value: string;
  /** Text shown for the option. */
  label: string;
  /** Icon before the label. */
  icon?: ReactNode;
  /** Count shown next to the option. Client-side tables count for you; pass it in server mode. */
  count?: number;
};

/** What a column's `cell` function receives for each row. */
export type DataTableCellContext<TData> = {
  /** The original row object. */
  row: TData;
  /** The row's id (from `getRowId`). */
  rowId: string;
  /** The column's accessor value. */
  value: unknown;
  /** Wraps the parts that match the current search in <mark>. */
  highlight: (text: string | number | null | undefined) => ReactNode;
  /** The applied (debounced) search text. */
  query: string;
  /** The current row density. */
  density: DataTableDensity;
};

/** Definition of one DataTable column. Only `id` and `header` are required. */
export type DataTableColumn<TData> = {
  /** Unique id. Also the accessor key when neither `accessorKey` nor `accessorFn` is set. */
  id: string;
  /** Header text. Also used for the column menu, CSV header, card labels and announcements. */
  header: string;
  /** Read the value from this key of the row. */
  accessorKey?: Extract<keyof TData, string>;
  /** Read the value with a function (for computed columns). */
  accessorFn?: (row: TData) => unknown;
  /** Custom cell. Defaults to the value as text, with search matches highlighted. */
  cell?: (ctx: DataTableCellContext<TData>) => ReactNode;
  /** Text alignment. Default "left" ("right" when `numeric`). */
  align?: DataTableAlign;
  /** Right-aligned, tabular figures, sorts numerically. */
  numeric?: boolean;
  /** Preferred width (CSS length or px number). For `wrap` columns it is also the minimum. */
  width?: number | string;
  /** Smallest width the column may shrink to (CSS length or px number). */
  minWidth?: number | string;
  /** Default true. */
  enableSorting?: boolean;
  /** Can be hidden from the View menu. Default true. */
  enableHiding?: boolean;
  /** Start hidden (uncontrolled visibility). */
  defaultHidden?: boolean;
  /** Included in the global search while the column is visible. Default true. */
  searchable?: boolean;
  /** Text the global search matches against. Default: the value as a string. */
  searchValue?: (row: TData) => string;
  /** "faceted": a multi-select filter with counts in the toolbar. */
  filter?: "faceted";
  /** Options for the faceted filter. Client-side tables derive them from the data when omitted. */
  filterOptions?: DataTableFilterOption[];
  /** Built-in sort name or a compare function on the original rows. */
  sortFn?: "alphanumeric" | "text" | "basic" | "datetime" | ((a: TData, b: TData) => number);
  /** Value written to CSV. Default: the accessor value. */
  exportValue?: (row: TData) => string | number | boolean | null | undefined;
  /** Include in CSV export. Default true. */
  enableExport?: boolean;
  /** Allow the cell text to wrap (cells are single-line by default). */
  wrap?: boolean;
  /** Hide this column in the mobile card layout. */
  hideInCards?: boolean;
  /** Extra classes for the header cell. */
  headerClassName?: string;
  /** Extra classes for every body cell of the column. */
  cellClassName?: string;
};

/** One item in a row's actions menu (the "⋯" button). */
export type DataTableRowAction<TData> = {
  /** Menu text. */
  label: string;
  /** Runs with the row when the item is chosen. */
  onSelect: (row: TData) => void;
  /** Icon before the label. */
  icon?: ReactNode;
  /** "danger" colours the item as destructive. Default "neutral". */
  tone?: "neutral" | "danger";
  /** Show the item but make it unselectable. */
  disabled?: boolean;
  /** Draw a divider above this item. */
  separatorBefore?: boolean;
};

/** One button in the floating selection bar. */
export type DataTableBulkAction<TData> = {
  /** Button text. */
  label: string;
  /** Receives the selected rows (also those on other pages) and a function that clears the selection. */
  onSelect: (rows: TData[], clearSelection: () => void) => void;
  /** Icon before the label. */
  icon?: ReactNode;
  /** "danger" colours the button as destructive. Default "neutral". */
  tone?: "neutral" | "danger";
};

/**
 * Every UI string of {@link DataTable}, for translation: pass a partial through its `labels` prop.
 * Keys that are functions get the counts or names to build a sentence. The English defaults are
 * `defaultDataTableLabels`.
 */
export type DataTableLabels = {
  searchLabel: string;
  searchPlaceholder: string;
  clearSearch: string;
  /** Announced and shown after searching or filtering. */
  results: (count: number) => string;
  clearFilters: string;
  filterChipsLabel: string;
  /** Accessible name of a filter chip's remove button. */
  removeFilter: (column: string, value: string) => string;
  /** Accessible name of a faceted filter trigger, e.g. "Filter by Status, 2 selected". Keep the column name in it. */
  filterSelected: (column: string, count: number) => string;
  clearFilter: string;
  view: string;
  columns: string;
  density: string;
  comfortable: string;
  compact: string;
  /** Toolbar export (all filtered rows). Also the visible text of the selection bar's export button. */
  exportCsv: string;
  /** Accessible name of the selection bar's export button. Should start with `exportCsv`. */
  exportSelected: string;
  sortBy: string;
  sortDefault: string;
  sortOptionAsc: (column: string) => string;
  sortOptionDesc: (column: string) => string;
  /** Accessible name of the header checkbox. */
  selectAllOnPage: string;
  /** Accessible name of a row checkbox. */
  selectRow: (rowLabel: string) => string;
  allOnPageSelected: (count: number) => string;
  selectAllMatching: (count: number) => string;
  allSelected: (count: number) => string;
  clearSelection: string;
  selectedCount: (count: number) => string;
  /** Selection bar note when selected rows are hidden by the search or filters. */
  hiddenSelected: (count: number) => string;
  /** Screen-reader text after a faceted option's count, e.g. "28 rows". */
  facetCount: (count: number) => string;
  bulkActions: string;
  rowActions: (rowLabel: string) => string;
  actionsColumn: string;
  expandColumn: string;
  /** Accessible name of the expand toggle. Should start with `showDetails` / `hideDetails`. */
  expandRow: (rowLabel: string) => string;
  collapseRow: (rowLabel: string) => string;
  /** Visible text of the expand toggle in the card layout. */
  showDetails: string;
  hideDetails: string;
  /** Screen-reader hint on sortable headers. */
  sortHint: string;
  sortAscending: string;
  sortDescending: string;
  sortPriority: (priority: number) => string;
  sortedBy: (description: string) => string;
  sortCleared: string;
  sortThen: string;
  rowsPerPage: string;
  /** e.g. "Showing 21–40 of 312". */
  showing: (from: number, to: number, total: number) => string;
  pageOf: (page: number, pageCount: number) => string;
  /** Announced when the page size changes. */
  pageSizeChanged: (pageSize: number, page: number, pageCount: number) => string;
  /** Name of the scroll region when the table overflows (it is not a landmark otherwise). */
  scrollRegion: (caption: string) => string;
  goToPage: string;
  loading: string;
  refreshing: string;
  empty: string;
  emptyDescription: string;
  emptyForQuery: (query: string) => string;
  emptyFiltered: string;
  emptyFilteredDescription: string;
  errorTitle: string;
  retry: string;
  pagination: Partial<PaginationLabels>;
};

/** Props of {@link DataTable}. Only `data`, `columns` and `caption` are required. */
export type DataTableProps<TData> = {
  /** The rows. With server-side mode, only the current page. */
  data: TData[];
  /** Column definitions; see {@link DataTableColumn}. */
  columns: DataTableColumn<TData>[];
  /** Returns a stable id for a row; it is the row's React key and keys the selection and expansion state. Default: `row.id` when present, otherwise the index. */
  getRowId?: (row: TData, index: number) => string;
  /** Short name for a row, used in labels ("Select row Ravi Kumar"). Default: the first column's value. */
  getRowLabel?: (row: TData) => string;
  /** Table caption: names the table for screen readers. */
  caption: string;
  /** Show the caption visually (it is visually hidden by default). */
  showCaption?: boolean;
  /** Sets the id of the table element. */
  id?: string;
  /** Accessible name of the scroll region (a landmark only while the table overflows). Default: labels.scrollRegion(caption). */
  "aria-label"?: string;
  /** Class for the outer wrapper (toolbar + table + footer). */
  className?: string;
  /** Class for the glass panel around the table. */
  tableClassName?: string;

  // ---- Features (all optional, sensible defaults) ----
  /** Shows a search box that filters every column. Default true. */
  enableSearch?: boolean;
  /** Delay in ms before typing in the search box filters the rows. Default 200. */
  searchDebounceMs?: number;
  /** Checkbox column, select-all and the bulk-actions bar. Default false. */
  enableSelection?: boolean;
  /** Adds column visibility and density options to a View menu. Default true. */
  enableViewOptions?: boolean;
  /** Shows a button that exports the rows as CSV. Default true. */
  enableExport?: boolean;
  /** File name of the CSV download (".csv" is added). */
  exportFilename?: string;
  /**
   * Replace the built-in CSV download. Receives the rows being exported, in table order.
   * With manual pagination the table only holds the current page, so the toolbar Export
   * is shown only when this is set: fetch the full export from your server here.
   */
  onExport?: (rows: TData[], scope: "filtered" | "selected") => void;
  /** Lets people sort by clicking a column header; set false to turn sorting off for the whole table. Default true. */
  enableSorting?: boolean;
  /** Shift-click headers to sort by more than one column. Default true. */
  enableMultiSort?: boolean;
  /**
   * Pin the first data column (and the checkbox / expand columns) while scrolling sideways.
   * Under 640px the pinned columns are capped at about 45% of the screen. Default true.
   */
  stickyFirstColumn?: boolean;
  /**
   * Slide rows to their new place when sorting, filtering or paging reorders them (Motion `layout`,
   * transform only, `spring.smooth`; rows are measured once per change). Instant with reduced motion.
   * Default true.
   */
  animateRows?: boolean;
  /**
   * Render only the rows in view (plus a few more) with spacers for the rest, so a long page (100 rows) sorts and
   * scrolls without a long task. `"auto"` windows a page of 50 rows or more when `maxHeight` is set and the layout
   * is the table (not cards). Rows are measured as they render, expanded panels included. Rows outside the window are
   * not in the DOM, so Tab skips them and a focused row that scrolls out loses focus: set `false` for tables people
   * tab through row by row. Default "auto".
   */
  virtualize?: boolean | "auto";
  /** Max height of the scroll area; the header sticks to its top. */
  maxHeight?: string;
  /** Page sizes offered in the footer. Default [10, 20, 50]. */
  pageSizeOptions?: number[];
  /** Sets the starting page size when uncontrolled. Default 10. */
  defaultPageSize?: number;
  /** Hide the footer (pagination). Default false. */
  hidePagination?: boolean;
  /** Items of the ⋯ menu at the end of each row: a list, or a function that returns one for a row. */
  rowActions?: DataTableRowAction<TData>[] | ((row: TData) => DataTableRowAction<TData>[]);
  /** Detail panel shown under an expanded row. Enables the chevron column. */
  renderExpanded?: (row: TData) => ReactNode;
  /** Shows the buttons in the floating selection bar. */
  bulkActions?: DataTableBulkAction<TData>[];
  /** Extra controls at the start / end of the toolbar. */
  toolbarLeft?: ReactNode;
  /** Extra controls at the end of the toolbar. */
  toolbarRight?: ReactNode;
  /** "cards": rows become glass cards under 640px. Default "scroll" (the table scrolls sideways). */
  mobileLayout?: "scroll" | "cards";

  // ---- States ----
  /** First load (skeleton) or, when rows are present, a refetch (rows stay, dimmed). */
  loading?: boolean;
  /** Shows an error message (or true for the default). */
  error?: ReactNode;
  /** Called by the error state's Retry button. Without it the button is hidden. */
  onRetry?: () => void;
  /** Custom empty state (replaces the default). */
  emptyState?: ReactNode;

  // ---- Density ----
  /** Row height, controlled: "comfortable" or "compact". Pair with `onDensityChange`; the View menu changes it. */
  density?: DataTableDensity;
  /**
   * Sets the starting density when uncontrolled.
   * @default "comfortable"
   */
  defaultDensity?: DataTableDensity;
  /** Called with the new density from the View menu. */
  onDensityChange?: (density: DataTableDensity) => void;

  // ---- Controlled state (all optional; callbacks receive the next value) ----
  /** Current sort order, as an array of column id and direction; pass it with `onSortingChange` to control sorting. */
  sorting?: DataTableSorting;
  /** Sets the starting sorting when uncontrolled. */
  defaultSorting?: DataTableSorting;
  /** Called with the next sorting. */
  onSortingChange?: (sorting: DataTableSorting) => void;
  /** Sets the page index and size when controlled. */
  pagination?: DataTablePagination;
  /** Called with the next page index and size. */
  onPaginationChange?: (pagination: DataTablePagination) => void;
  /** Current search text; pass it with `onGlobalFilterChange` to control the search box. */
  globalFilter?: string;
  /** Initial search text when uncontrolled (a pre-filled search box). */
  defaultGlobalFilter?: string;
  /** Called with the applied (debounced) search text. */
  onGlobalFilterChange?: (value: string) => void;
  /** Currently applied faceted filters; pass it with `onColumnFiltersChange` to control them. */
  columnFilters?: DataTableColumnFilters;
  /** Sets the starting faceted filters when uncontrolled. */
  defaultColumnFilters?: DataTableColumnFilters;
  /** Called with the next faceted filters. */
  onColumnFiltersChange?: (filters: DataTableColumnFilters) => void;
  /** Selected row ids (controlled). */
  rowSelection?: DataTableRowSelection;
  /** Sets the row ids selected at first when uncontrolled (`{ [rowId]: true }`). */
  defaultRowSelection?: DataTableRowSelection;
  /** Called with the next selection. */
  onRowSelectionChange?: (selection: DataTableRowSelection) => void;
  /** Which columns are shown, keyed by column id; pass it with `onColumnVisibilityChange` to control it. */
  columnVisibility?: DataTableColumnVisibility;
  /** Called with the next visibility map. */
  onColumnVisibilityChange?: (visibility: DataTableColumnVisibility) => void;

  // ---- Server-side mode ----
  /** Works as shorthand for manualPagination + manualSorting + manualFiltering. */
  manual?: boolean;
  /** `data` is already the current page; use `rowCount` for the total. */
  manualPagination?: boolean;
  /** `data` is already sorted. */
  manualSorting?: boolean;
  /** `data` is already searched and filtered. */
  manualFiltering?: boolean;
  /** Sets the total rows on the server (manual pagination). */
  rowCount?: number;

  /** UI strings (i18n). */
  labels?: Partial<DataTableLabels>;
};

